import type { NistCatalogFamily } from "../types.js";

// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_AC: NistCatalogFamily = {"code":"AC","name":"Access Control","controls":[{"id":"AC-1","oscal_id":"ac-1","family":"AC","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> access control policy that:\n    <organization-defined parameter> access control policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the access control policy and the associated access controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the access control policy and procedures; and\nc. Review and update the current access control:\n  Review and update the current access control:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Access control policy and procedures address the controls in the AC family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of access control policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to access control policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"ac-1_prm_1","label":"organization-defined personnel or roles"},{"id":"ac-01_odp.01","label":"personnel or roles"},{"id":"ac-01_odp.02","label":"personnel or roles"},{"id":"ac-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"ac-01_odp.04","label":"official"},{"id":"ac-01_odp.05","label":"frequency"},{"id":"ac-01_odp.06","label":"events"},{"id":"ac-01_odp.07","label":"frequency"},{"id":"ac-01_odp.08","label":"events"}],"objectives":[{"id":"ac-1_obj.a-1","label":"AC-01a.[01]","text":"an access control policy is developed and documented;"},{"id":"ac-1_obj.a-2","label":"AC-01a.[02]","text":"the access control policy is disseminated to {{ insert: param, ac-01_odp.01 }};"},{"id":"ac-1_obj.a-3","label":"AC-01a.[03]","text":"access control procedures to facilitate the implementation of the access control policy and associated controls are developed and documented;"},{"id":"ac-1_obj.a-4","label":"AC-01a.[04]","text":"the access control procedures are disseminated to {{ insert: param, ac-01_odp.02 }};"},{"id":"ac-1_obj.a.1.a-1","label":"AC-01a.01(a)[01]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses purpose;"},{"id":"ac-1_obj.a.1.a-2","label":"AC-01a.01(a)[02]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses scope;"},{"id":"ac-1_obj.a.1.a-3","label":"AC-01a.01(a)[03]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses roles;"},{"id":"ac-1_obj.a.1.a-4","label":"AC-01a.01(a)[04]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses responsibilities;"},{"id":"ac-1_obj.a.1.a-5","label":"AC-01a.01(a)[05]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses management commitment;"},{"id":"ac-1_obj.a.1.a-6","label":"AC-01a.01(a)[06]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses coordination among organizational entities;"},{"id":"ac-1_obj.a.1.a-7","label":"AC-01a.01(a)[07]","text":"the {{ insert: param, ac-01_odp.03 }} access control policy addresses compliance;"},{"id":"ac-1_obj.a.1.b","label":"AC-01a.01(b)","text":"the {{ insert: param, ac-01_odp.03 }} access control policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"ac-1_obj.b","label":"AC-01b.","text":"the {{ insert: param, ac-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the access control policy and procedures;"},{"id":"ac-1_obj.c.1-1","label":"AC-01c.01[01]","text":"the current access control policy is reviewed and updated {{ insert: param, ac-01_odp.05 }};"},{"id":"ac-1_obj.c.1-2","label":"AC-01c.01[02]","text":"the current access control policy is reviewed and updated following {{ insert: param, ac-01_odp.06 }};"},{"id":"ac-1_obj.c.2-1","label":"AC-01c.02[01]","text":"the current access control procedures are reviewed and updated {{ insert: param, ac-01_odp.07 }};"},{"id":"ac-1_obj.c.2-2","label":"AC-01c.02[02]","text":"the current access control procedures are reviewed and updated following {{ insert: param, ac-01_odp.08 }}."}],"methods":[{"method":"examine","label":"AC-01-Examine"},{"method":"interview","label":"AC-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"},{"title":"IR 7874"}],"related_controls":["IA-1","PM-9","PM-24","PS-8","SI-12"]},{"id":"AC-2","oscal_id":"ac-2","family":"AC","title":"Account Management","statement":"a. Define and document the types of accounts allowed and specifically prohibited for use within the system;\nb. Assign account managers;\nc. Require <prerequisites and criteria> for group and role membership;\nd. Specify:\n  Specify:\n  1. Authorized users of the system;\n  2. Group and role membership; and\n  3. Access authorizations (i.e., privileges) and <attributes (as required)> for each account;\ne. Require approvals by <personnel or roles> for requests to create accounts;\nf. Create, enable, modify, disable, and remove accounts in accordance with <policy, procedures, prerequisites, and criteria>;\ng. Monitor the use of accounts;\nh. Notify account managers and <personnel or roles> within:\n  Notify account managers and <personnel or roles> within:\n  1. <time period> when accounts are no longer required;\n  2. <time period> when users are terminated or transferred; and\n  3. <time period> when system usage or need-to-know changes for an individual;\ni. Authorize access to the system based on:\n  Authorize access to the system based on:\n  1. A valid access authorization;\n  2. Intended system usage; and\n  3. <attributes (as required)>;\nj. Review accounts for compliance with account management requirements <frequency>;\nk. Establish and implement a process for changing shared or group account authenticators (if deployed) when individuals are removed from the group; and\nl. Align account management processes with personnel termination and transfer processes.","supplemental_guidance":"Examples of system account types include individual, shared, group, system, guest, anonymous, emergency, developer, temporary, and service. Identification of authorized system users and the specification of access privileges reflect the requirements in other controls in the security plan. Users requiring administrative privileges on system accounts receive additional scrutiny by organizational personnel responsible for approving such accounts and privileged access, including system owner, mission or business owner, senior agency information security officer, or senior agency official for privacy. Types of accounts that organizations may wish to prohibit due to increased risk include shared, group, emergency, anonymous, temporary, and guest accounts.\n\nWhere access involves personally identifiable information, security programs collaborate with the senior agency official for privacy to establish the specific conditions for group and role membership; specify authorized users, group and role membership, and access authorizations for each account; and create, adjust, or remove system accounts in accordance with organizational policies. Policies can include such information as account expiration dates or other factors that trigger the disabling of accounts. Organizations may choose to define access privileges or other attributes by account, type of account, or a combination of the two. Examples of other attributes required for authorizing access include restrictions on time of day, day of week, and point of origin. In defining other system account attributes, organizations consider system-related requirements and mission/business requirements. Failure to consider these factors could affect system availability.\n\nTemporary and emergency accounts are intended for short-term use. Organizations establish temporary accounts as part of normal account activation procedures when there is a need for short-term accounts without the demand for immediacy in account activation. Organizations establish emergency accounts in response to crisis situations and with the need for rapid account activation. Therefore, emergency account activation may bypass normal account authorization processes. Emergency and temporary accounts are not to be confused with infrequently used accounts, including local logon accounts used for special tasks or when network resources are unavailable (may also be known as accounts of last resort). Such accounts remain available and are not subject to automatic disabling or removal dates. Conditions for disabling or deactivating accounts include when shared/group, emergency, or temporary accounts are no longer required and when individuals are transferred or terminated. Changing shared/group authenticators when members leave the group is intended to ensure that former group members do not retain access to the shared or group account. Some types of system accounts may require specialized training.","implementation_level":"organization","parameters":[{"id":"ac-02_odp.01","label":"prerequisites and criteria"},{"id":"ac-02_odp.02","label":"attributes (as required)"},{"id":"ac-02_odp.03","label":"personnel or roles"},{"id":"ac-02_odp.04","label":"policy, procedures, prerequisites, and criteria"},{"id":"ac-02_odp.05","label":"personnel or roles"},{"id":"ac-02_odp.06","label":"time period"},{"id":"ac-02_odp.07","label":"time period"},{"id":"ac-02_odp.08","label":"time period"},{"id":"ac-02_odp.09","label":"attributes (as required)"},{"id":"ac-02_odp.10","label":"frequency"}],"objectives":[{"id":"ac-2_obj.a-1","label":"AC-02a.[01]","text":"account types allowed for use within the system are defined and documented;"},{"id":"ac-2_obj.a-2","label":"AC-02a.[02]","text":"account types specifically prohibited for use within the system are defined and documented;"},{"id":"ac-2_obj.b","label":"AC-02b.","text":"account managers are assigned;"},{"id":"ac-2_obj.c","label":"AC-02c.","text":"{{ insert: param, ac-02_odp.01 }} for group and role membership are required;"},{"id":"ac-2_obj.d.1","label":"AC-02d.01","text":"authorized users of the system are specified;"},{"id":"ac-2_obj.d.2","label":"AC-02d.02","text":"group and role membership are specified;"},{"id":"ac-2_obj.d.3-1","label":"AC-02d.03[01]","text":"access authorizations (i.e., privileges) are specified for each account;"},{"id":"ac-2_obj.d.3-2","label":"AC-02d.03[02]","text":"{{ insert: param, ac-02_odp.02 }} are specified for each account;"},{"id":"ac-2_obj.e","label":"AC-02e.","text":"approvals are required by {{ insert: param, ac-02_odp.03 }} for requests to create accounts;"},{"id":"ac-2_obj.f-1","label":"AC-02f.[01]","text":"accounts are created in accordance with {{ insert: param, ac-02_odp.04 }};"},{"id":"ac-2_obj.f-2","label":"AC-02f.[02]","text":"accounts are enabled in accordance with {{ insert: param, ac-02_odp.04 }};"},{"id":"ac-2_obj.f-3","label":"AC-02f.[03]","text":"accounts are modified in accordance with {{ insert: param, ac-02_odp.04 }};"},{"id":"ac-2_obj.f-4","label":"AC-02f.[04]","text":"accounts are disabled in accordance with {{ insert: param, ac-02_odp.04 }};"},{"id":"ac-2_obj.f-5","label":"AC-02f.[05]","text":"accounts are removed in accordance with {{ insert: param, ac-02_odp.04 }};"},{"id":"ac-2_obj.g","label":"AC-02g.","text":"the use of accounts is monitored;"},{"id":"ac-2_obj.h.1","label":"AC-02h.01","text":"account managers and {{ insert: param, ac-02_odp.05 }} are notified within {{ insert: param, ac-02_odp.06 }} when accounts are no longer required;"},{"id":"ac-2_obj.h.2","label":"AC-02h.02","text":"account managers and {{ insert: param, ac-02_odp.05 }} are notified within {{ insert: param, ac-02_odp.07 }} when users are terminated or transferred;"},{"id":"ac-2_obj.h.3","label":"AC-02h.03","text":"account managers and {{ insert: param, ac-02_odp.05 }} are notified within {{ insert: param, ac-02_odp.08 }} when system usage or the need to know changes for an individual;"},{"id":"ac-2_obj.i.1","label":"AC-02i.01","text":"access to the system is authorized based on a valid access authorization;"},{"id":"ac-2_obj.i.2","label":"AC-02i.02","text":"access to the system is authorized based on intended system usage;"},{"id":"ac-2_obj.i.3","label":"AC-02i.03","text":"access to the system is authorized based on {{ insert: param, ac-02_odp.09 }};"},{"id":"ac-2_obj.j","label":"AC-02j.","text":"accounts are reviewed for compliance with account management requirements {{ insert: param, ac-02_odp.10 }};"},{"id":"ac-2_obj.k-1","label":"AC-02k.[01]","text":"a process is established for changing shared or group account authenticators (if deployed) when individuals are removed from the group;"},{"id":"ac-2_obj.k-2","label":"AC-02k.[02]","text":"a process is implemented for changing shared or group account authenticators (if deployed) when individuals are removed from the group;"},{"id":"ac-2_obj.l-1","label":"AC-02l.[01]","text":"account management processes are aligned with personnel termination processes;"},{"id":"ac-2_obj.l-2","label":"AC-02l.[02]","text":"account management processes are aligned with personnel transfer processes."}],"methods":[{"method":"examine","label":"AC-02-Examine"},{"method":"interview","label":"AC-02-Interview"},{"method":"test","label":"AC-02-Test"}],"references":[{"title":"SP 800-162"},{"title":"SP 800-178"},{"title":"SP 800-192"}],"related_controls":["AC-3","AC-5","AC-6","AC-17","AC-18","AC-20","AC-24","AU-2","AU-12","CM-5","IA-2","IA-4","IA-5","IA-8","MA-3","MA-5","PE-2","PL-4","PS-2","PS-4","PS-5","PS-7","PT-2","PT-3","SC-7","SC-12","SC-13","SC-37"],"enhancements":[{"id":"AC-2(1)","oscal_id":"ac-2.1","family":"AC","title":"Automated System Account Management","statement":"Support the management of system accounts using <automated mechanisms>.","supplemental_guidance":"Automated system account management includes using automated mechanisms to create, enable, modify, disable, and remove accounts; notify account managers when an account is created, enabled, modified, disabled, or removed, or when users are terminated or transferred; monitor system account usage; and report atypical system account usage. Automated mechanisms can include internal system functions and email, telephonic, and text messaging notifications.","implementation_level":"organization","parameters":[{"id":"ac-02.01_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"AC-02(01)-Examine"},{"method":"interview","label":"AC-02(01)-Interview"},{"method":"test","label":"AC-02(01)-Test"}],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(2)","oscal_id":"ac-2.2","family":"AC","title":"Automated Temporary and Emergency Account Management","statement":"Automatically <organization-defined parameter> temporary and emergency accounts after <time period>.","supplemental_guidance":"Management of temporary and emergency accounts includes the removal or disabling of such accounts automatically after a predefined time period rather than at the convenience of the system administrator. Automatic removal or disabling of accounts provides a more consistent implementation.","implementation_level":"system","parameters":[{"id":"ac-02.02_odp.01","label":"","choices":["remove","disable"]},{"id":"ac-02.02_odp.02","label":"time period"}],"methods":[{"method":"examine","label":"AC-02(02)-Examine"},{"method":"interview","label":"AC-02(02)-Interview"},{"method":"test","label":"AC-02(02)-Test"}],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(3)","oscal_id":"ac-2.3","family":"AC","title":"Disable Accounts","statement":"Disable accounts within <time period> when the accounts:\n(a) Have expired;\n(b) Are no longer associated with a user or individual;\n(c) Are in violation of organizational policy; or\n(d) Have been inactive for <time period>.","supplemental_guidance":"Disabling expired, inactive, or otherwise anomalous accounts supports the concepts of least privilege and least functionality which reduce the attack surface of the system.","implementation_level":"system","parameters":[{"id":"ac-02.03_odp.01","label":"time period"},{"id":"ac-02.03_odp.02","label":"time period"}],"objectives":[{"id":"ac-2.3_obj.a","label":"AC-02(03)(a)","text":"accounts are disabled within {{ insert: param, ac-02.03_odp.01 }} when the accounts have expired;"},{"id":"ac-2.3_obj.b","label":"AC-02(03)(b)","text":"accounts are disabled within {{ insert: param, ac-02.03_odp.01 }} when the accounts are no longer associated with a user or individual;"},{"id":"ac-2.3_obj.c","label":"AC-02(03)(c)","text":"accounts are disabled within {{ insert: param, ac-02.03_odp.01 }} when the accounts are in violation of organizational policy;"},{"id":"ac-2.3_obj.d","label":"AC-02(03)(d)","text":"accounts are disabled within {{ insert: param, ac-02.03_odp.01 }} when the accounts have been inactive for {{ insert: param, ac-02.03_odp.02 }}."}],"methods":[{"method":"examine","label":"AC-02(03)-Examine"},{"method":"interview","label":"AC-02(03)-Interview"},{"method":"test","label":"AC-02(03)-Test"}],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(4)","oscal_id":"ac-2.4","family":"AC","title":"Automated Audit Actions","statement":"Automatically audit account creation, modification, enabling, disabling, and removal actions.","supplemental_guidance":"Account management audit records are defined in accordance with [AU-02](#au-2) and reviewed, analyzed, and reported in accordance with [AU-06](#au-6).","implementation_level":"system","objectives":[{"id":"ac-2.4_obj-1","label":"AC-02(04)[01]","text":"account creation is automatically audited;"},{"id":"ac-2.4_obj-2","label":"AC-02(04)[02]","text":"account modification is automatically audited;"},{"id":"ac-2.4_obj-3","label":"AC-02(04)[03]","text":"account enabling is automatically audited;"},{"id":"ac-2.4_obj-4","label":"AC-02(04)[04]","text":"account disabling is automatically audited;"},{"id":"ac-2.4_obj-5","label":"AC-02(04)[05]","text":"account removal actions are automatically audited."}],"methods":[{"method":"examine","label":"AC-02(04)-Examine"},{"method":"interview","label":"AC-02(04)-Interview"},{"method":"test","label":"AC-02(04)-Test"}],"related_controls":["AU-2","AU-6"],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(5)","oscal_id":"ac-2.5","family":"AC","title":"Inactivity Logout","statement":"Require that users log out when <time period of expected inactivity or description of when to log out>.","supplemental_guidance":"Inactivity logout is behavior- or policy-based and requires users to take physical action to log out when they are expecting inactivity longer than the defined period. Automatic enforcement of inactivity logout is addressed by [AC-11](#ac-11).","implementation_level":"organization","parameters":[{"id":"ac-02.05_odp","label":"time period of expected inactivity or description of when to log out"}],"methods":[{"method":"examine","label":"AC-02(05)-Examine"},{"method":"interview","label":"AC-02(05)-Interview"}],"related_controls":["AC-11"],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(6)","oscal_id":"ac-2.6","family":"AC","title":"Dynamic Privilege Management","statement":"Implement <dynamic privilege management capabilities>.","supplemental_guidance":"In contrast to access control approaches that employ static accounts and predefined user privileges, dynamic access control approaches rely on runtime access control decisions facilitated by dynamic privilege management, such as attribute-based access control. While user identities remain relatively constant over time, user privileges typically change more frequently based on ongoing mission or business requirements and the operational needs of organizations. An example of dynamic privilege management is the immediate revocation of privileges from users as opposed to requiring that users terminate and restart their sessions to reflect changes in privileges. Dynamic privilege management can also include mechanisms that change user privileges based on dynamic rules as opposed to editing specific user profiles. Examples include automatic adjustments of user privileges if they are operating out of their normal work times, if their job function or assignment changes, or if systems are under duress or in emergency situations. Dynamic privilege management includes the effects of privilege changes, for example, when there are changes to encryption keys used for communications.","implementation_level":"system","parameters":[{"id":"ac-02.06_odp","label":"dynamic privilege management capabilities"}],"methods":[{"method":"examine","label":"AC-02(06)-Examine"},{"method":"interview","label":"AC-02(06)-Interview"},{"method":"test","label":"AC-02(06)-Test"}],"related_controls":["AC-16"],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(7)","oscal_id":"ac-2.7","family":"AC","title":"Privileged User Accounts","statement":"(a) Establish and administer privileged user accounts in accordance with <organization-defined parameter>;\n(b) Monitor privileged role or attribute assignments;\n(c) Monitor changes to roles or attributes; and\n(d) Revoke access when privileged role or attribute assignments are no longer appropriate.","supplemental_guidance":"Privileged roles are organization-defined roles assigned to individuals that allow those individuals to perform certain security-relevant functions that ordinary users are not authorized to perform. Privileged roles include key management, account management, database administration, system and network administration, and web administration. A role-based access scheme organizes permitted system access and privileges into roles. In contrast, an attribute-based access scheme specifies allowed system access and privileges based on attributes.","implementation_level":"organization","parameters":[{"id":"ac-02.07_odp","label":"","choices":["a role-based access scheme","an attribute-based access scheme"]}],"objectives":[{"id":"ac-2.7_obj.a","label":"AC-02(07)(a)","text":"privileged user accounts are established and administered in accordance with {{ insert: param, ac-02.07_odp }};"},{"id":"ac-2.7_obj.b","label":"AC-02(07)(b)","text":"privileged role or attribute assignments are monitored;"},{"id":"ac-2.7_obj.c","label":"AC-02(07)(c)","text":"changes to roles or attributes are monitored;"},{"id":"ac-2.7_obj.d","label":"AC-02(07)(d)","text":"access is revoked when privileged role or attribute assignments are no longer appropriate."}],"methods":[{"method":"examine","label":"AC-02(07)-Examine"},{"method":"interview","label":"AC-02(07)-Interview"},{"method":"test","label":"AC-02(07)-Test"}],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(8)","oscal_id":"ac-2.8","family":"AC","title":"Dynamic Account Management","statement":"Create, activate, manage, and deactivate <system accounts> dynamically.","supplemental_guidance":"Approaches for dynamically creating, activating, managing, and deactivating system accounts rely on automatically provisioning the accounts at runtime for entities that were previously unknown. Organizations plan for the dynamic management, creation, activation, and deactivation of system accounts by establishing trust relationships, business rules, and mechanisms with appropriate authorities to validate related authorizations and privileges.","implementation_level":"system","parameters":[{"id":"ac-02.08_odp","label":"system accounts"}],"objectives":[{"id":"ac-2.8_obj-1","label":"AC-02(08)[01]","text":"{{ insert: param, ac-02.08_odp }} are created dynamically;"},{"id":"ac-2.8_obj-2","label":"AC-02(08)[02]","text":"{{ insert: param, ac-02.08_odp }} are activated dynamically;"},{"id":"ac-2.8_obj-3","label":"AC-02(08)[03]","text":"{{ insert: param, ac-02.08_odp }} are managed dynamically;"},{"id":"ac-2.8_obj-4","label":"AC-02(08)[04]","text":"{{ insert: param, ac-02.08_odp }} are deactivated dynamically."}],"methods":[{"method":"examine","label":"AC-02(08)-Examine"},{"method":"interview","label":"AC-02(08)-Interview"},{"method":"test","label":"AC-02(08)-Test"}],"related_controls":["AC-16"],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(9)","oscal_id":"ac-2.9","family":"AC","title":"Restrictions on Use of Shared and Group Accounts","statement":"Only permit the use of shared and group accounts that meet <conditions>.","supplemental_guidance":"Before permitting the use of shared or group accounts, organizations consider the increased risk due to the lack of accountability with such accounts.","implementation_level":"organization","parameters":[{"id":"ac-02.09_odp","label":"conditions"}],"methods":[{"method":"examine","label":"AC-02(09)-Examine"},{"method":"interview","label":"AC-02(09)-Interview"},{"method":"test","label":"AC-02(09)-Test"}],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(10)","oscal_id":"ac-2.10","family":"AC","title":"Shared and Group Account Credential Change","statement":"","is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(11)","oscal_id":"ac-2.11","family":"AC","title":"Usage Conditions","statement":"Enforce <circumstances and/or usage conditions> for <system accounts>.","supplemental_guidance":"Specifying and enforcing usage conditions helps to enforce the principle of least privilege, increase user accountability, and enable effective account monitoring. Account monitoring includes alerts generated if the account is used in violation of organizational parameters. Organizations can describe specific conditions or circumstances under which system accounts can be used, such as by restricting usage to certain days of the week, time of day, or specific durations of time.","implementation_level":"system","parameters":[{"id":"ac-02.11_odp.01","label":"circumstances and/or usage conditions"},{"id":"ac-02.11_odp.02","label":"system accounts"}],"methods":[{"method":"examine","label":"AC-02(11)-Examine"},{"method":"interview","label":"AC-02(11)-Interview"},{"method":"test","label":"AC-02(11)-Test"}],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(12)","oscal_id":"ac-2.12","family":"AC","title":"Account Monitoring for Atypical Usage","statement":"(a) Monitor system accounts for <atypical usage> ; and\n(b) Report atypical usage of system accounts to <personnel or roles>.","supplemental_guidance":"Atypical usage includes accessing systems at certain times of the day or from locations that are not consistent with the normal usage patterns of individuals. Monitoring for atypical usage may reveal rogue behavior by individuals or an attack in progress. Account monitoring may inadvertently create privacy risks since data collected to identify atypical usage may reveal previously unknown information about the behavior of individuals. Organizations assess and document privacy risks from monitoring accounts for atypical usage in their privacy impact assessment and make determinations that are in alignment with their privacy program plan.","implementation_level":"organization","parameters":[{"id":"ac-02.12_odp.01","label":"atypical usage"},{"id":"ac-02.12_odp.02","label":"personnel or roles"}],"objectives":[{"id":"ac-2.12_obj.a","label":"AC-02(12)(a)","text":"system accounts are monitored for {{ insert: param, ac-02.12_odp.01 }};"},{"id":"ac-2.12_obj.b","label":"AC-02(12)(b)","text":"atypical usage of system accounts is reported to {{ insert: param, ac-02.12_odp.02 }}."}],"methods":[{"method":"examine","label":"AC-02(12)-Examine"},{"method":"interview","label":"AC-02(12)-Interview"},{"method":"test","label":"AC-02(12)-Test"}],"related_controls":["AU-6","AU-7","CA-7","IR-8","SI-4"],"is_enhancement":true,"parent_id":"AC-2"},{"id":"AC-2(13)","oscal_id":"ac-2.13","family":"AC","title":"Disable Accounts for High-risk Individuals","statement":"Disable accounts of individuals within <time period> of discovery of <significant risks>.","supplemental_guidance":"Users who pose a significant security and/or privacy risk include individuals for whom reliable evidence indicates either the intention to use authorized access to systems to cause harm or through whom adversaries will cause harm. Such harm includes adverse impacts to organizational operations, organizational assets, individuals, other organizations, or the Nation. Close coordination among system administrators, legal staff, human resource managers, and authorizing officials is essential when disabling system accounts for high-risk individuals.","implementation_level":"organization","parameters":[{"id":"ac-02.13_odp.01","label":"time period"},{"id":"ac-02.13_odp.02","label":"significant risks"}],"methods":[{"method":"examine","label":"AC-02(13)-Examine"},{"method":"interview","label":"AC-02(13)-Interview"},{"method":"test","label":"AC-02(13)-Test"}],"related_controls":["AU-6","SI-4"],"is_enhancement":true,"parent_id":"AC-2"}]},{"id":"AC-3","oscal_id":"ac-3","family":"AC","title":"Access Enforcement","statement":"Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies.","supplemental_guidance":"Access control policies control access between active entities or subjects (i.e., users or processes acting on behalf of users) and passive entities or objects (i.e., devices, files, records, domains) in organizational systems. In addition to enforcing authorized access at the system level and recognizing that systems can host many applications and services in support of mission and business functions, access enforcement mechanisms can also be employed at the application and service level to provide increased information security and privacy. In contrast to logical access controls that are implemented within the system, physical access controls are addressed by the controls in the Physical and Environmental Protection ( [PE](#pe) ) family.","implementation_level":"system","methods":[{"method":"examine","label":"AC-03-Examine"},{"method":"interview","label":"AC-03-Interview"},{"method":"test","label":"AC-03-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-130"},{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"},{"title":"SP 800-162"},{"title":"SP 800-178"},{"title":"IR 7874"}],"related_controls":["AC-2","AC-4","AC-5","AC-6","AC-16","AC-17","AC-18","AC-19","AC-20","AC-21","AC-22","AC-24","AC-25","AT-2","AT-3","AU-9","CA-9","CM-5","CM-11","IA-2","IA-5","IA-6","IA-7","IA-11","IA-13","MA-3","MA-4","MA-5","MP-4","PM-2","PS-3","PT-2","PT-3","SA-17","SC-2","SC-3","SC-4","SC-12","SC-13","SC-28","SC-31","SC-34","SI-4","SI-8"],"enhancements":[{"id":"AC-3(1)","oscal_id":"ac-3.1","family":"AC","title":"Restricted Access to Privileged Functions","statement":"","is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(2)","oscal_id":"ac-3.2","family":"AC","title":"Dual Authorization","statement":"Enforce dual authorization for <privileged commands and/or other actions>.","supplemental_guidance":"Dual authorization, also known as two-person control, reduces risk related to insider threats. Dual authorization mechanisms require the approval of two authorized individuals to execute. To reduce the risk of collusion, organizations consider rotating dual authorization duties. Organizations consider the risk associated with implementing dual authorization mechanisms when immediate responses are necessary to ensure public and environmental safety.","implementation_level":"system","parameters":[{"id":"ac-03.02_odp","label":"privileged commands and/or other actions"}],"methods":[{"method":"examine","label":"AC-03(02)-Examine"},{"method":"interview","label":"AC-03(02)-Interview"},{"method":"test","label":"AC-03(02)-Test"}],"related_controls":["CP-9","MP-6"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(3)","oscal_id":"ac-3.3","family":"AC","title":"Mandatory Access Control","statement":"Enforce <organization-defined mandatory access control policy> over the set of covered subjects and objects specified in the policy, and where the policy:\n(a) Is uniformly enforced across the covered subjects and objects within the system;\n(b) Specifies that a subject that has been granted access to information is constrained from doing any of the following;\n  Specifies that a subject that has been granted access to information is constrained from doing any of the following;\n  (1) Passing the information to unauthorized subjects or objects;\n  (2) Granting its privileges to other subjects;\n  (3) Changing one or more security attributes (specified by the policy) on subjects, objects, the system, or system components;\n  (4) Choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects; and\n  (5) Changing the rules governing access control; and\n(c) Specifies that <subjects> may explicitly be granted <privileges> such that they are not limited by any defined subset (or all) of the above constraints.","supplemental_guidance":"Mandatory access control is a type of nondiscretionary access control. Mandatory access control policies constrain what actions subjects can take with information obtained from objects for which they have already been granted access. This prevents the subjects from passing the information to unauthorized subjects and objects. Mandatory access control policies constrain actions that subjects can take with respect to the propagation of access control privileges; that is, a subject with a privilege cannot pass that privilege to other subjects. The policy is uniformly enforced over all subjects and objects to which the system has control. Otherwise, the access control policy can be circumvented. This enforcement is provided by an implementation that meets the reference monitor concept as described in [AC-25](#ac-25) . The policy is bounded by the system (i.e., once the information is passed outside of the control of the system, additional means may be required to ensure that the constraints on the information remain in effect).\n\nThe trusted subjects described above are granted privileges consistent with the concept of least privilege (see [AC-6](#ac-6) ). Trusted subjects are only given the minimum privileges necessary for satisfying organizational mission/business needs relative to the above policy. The control is most applicable when there is a mandate that establishes a policy regarding access to controlled unclassified information or classified information and some users of the system are not authorized access to all such information resident in the system. Mandatory access control can operate in conjunction with discretionary access control as described in [AC-3(4)](#ac-3.4) . A subject constrained in its operation by mandatory access control policies can still operate under the less rigorous constraints of AC-3(4), but mandatory access control policies take precedence over the less rigorous constraints of AC-3(4). For example, while a mandatory access control policy imposes a constraint that prevents a subject from passing information to another subject operating at a different impact or classification level, AC-3(4) permits the subject to pass the information to any other subject with the same impact or classification level as the subject. Examples of mandatory access control policies include the Bell-LaPadula policy to protect confidentiality of information and the Biba policy to protect the integrity of information.","implementation_level":"system","parameters":[{"id":"ac-3.3_prm_1","label":"organization-defined mandatory access control policy"},{"id":"ac-03.03_odp.01","label":"mandatory access control policy"},{"id":"ac-03.03_odp.02","label":"mandatory access control policy"},{"id":"ac-03.03_odp.03","label":"subjects"},{"id":"ac-03.03_odp.04","label":"privileges"}],"objectives":[{"id":"ac-3.3_obj-1","label":"AC-03(03)[01]","text":"{{ insert: param, ac-03.03_odp.01 }} is enforced over the set of covered subjects specified in the policy;"},{"id":"ac-3.3_obj-2","label":"AC-03(03)[02]","text":"{{ insert: param, ac-03.03_odp.02 }} is enforced over the set of covered objects specified in the policy;"},{"id":"ac-3.3_obj.a-1","label":"AC-03(03)(a)[01]","text":"{{ insert: param, ac-03.03_odp.01 }} is uniformly enforced across the covered subjects within the system;"},{"id":"ac-3.3_obj.a-2","label":"AC-03(03)(a)[02]","text":"{{ insert: param, ac-03.03_odp.02 }} is uniformly enforced across the covered objects within the system;"},{"id":"ac-3.3_obj.b.1","label":"AC-03(03)(b)(01)","text":"{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from passing the information to unauthorized subjects or objects are enforced;"},{"id":"ac-3.3_obj.b.2","label":"AC-03(03)(b)(02)","text":"{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from granting its privileges to other subjects are enforced;"},{"id":"ac-3.3_obj.b.3","label":"AC-03(03)(b)(03)","text":"{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from changing one of more security attributes (specified by the policy) on subjects, objects, the system, or system components are enforced;"},{"id":"ac-3.3_obj.b.4","label":"AC-03(03)(b)(04)","text":"{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects are enforced;"},{"id":"ac-3.3_obj.b.5","label":"AC-03(03)(b)(05)","text":"{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that a subject that has been granted access to information is constrained from changing the rules governing access control are enforced;"},{"id":"ac-3.3_obj.c","label":"AC-03(03)(c)","text":"{{ insert: param, ac-03.03_odp.01 }} and {{ insert: param, ac-03.03_odp.02 }} specifying that {{ insert: param, ac-03.03_odp.03 }} may explicitly be granted {{ insert: param, ac-03.03_odp.04 }} such that they are not limited by any defined subset (or all) of the above constraints are enforced."}],"methods":[{"method":"examine","label":"AC-03(03)-Examine"},{"method":"interview","label":"AC-03(03)-Interview"},{"method":"test","label":"AC-03(03)-Test"}],"related_controls":["SC-7"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(4)","oscal_id":"ac-3.4","family":"AC","title":"Discretionary Access Control","statement":"Enforce <organization-defined discretionary access control policy> over the set of covered subjects and objects specified in the policy, and where the policy specifies that a subject that has been granted access to information can do one or more of the following:\n(a) Pass the information to any other subjects or objects;\n(b) Grant its privileges to other subjects;\n(c) Change security attributes on subjects, objects, the system, or the system’s components;\n(d) Choose the security attributes to be associated with newly created or revised objects; or\n(e) Change the rules governing access control.","supplemental_guidance":"When discretionary access control policies are implemented, subjects are not constrained with regard to what actions they can take with information for which they have already been granted access. Thus, subjects that have been granted access to information are not prevented from passing the information to other subjects or objects (i.e., subjects have the discretion to pass). Discretionary access control can operate in conjunction with mandatory access control as described in [AC-3(3)](#ac-3.3) and [AC-3(15)](#ac-3.15) . A subject that is constrained in its operation by mandatory access control policies can still operate under the less rigorous constraints of discretionary access control. Therefore, while [AC-3(3)](#ac-3.3) imposes constraints that prevent a subject from passing information to another subject operating at a different impact or classification level, [AC-3(4)](#ac-3.4) permits the subject to pass the information to any subject at the same impact or classification level. The policy is bounded by the system. Once the information is passed outside of system control, additional means may be required to ensure that the constraints remain in effect. While traditional definitions of discretionary access control require identity-based access control, that limitation is not required for this particular use of discretionary access control.","implementation_level":"system","parameters":[{"id":"ac-3.4_prm_1","label":"organization-defined discretionary access control policy"},{"id":"ac-03.04_odp.01","label":"discretionary access control policy"},{"id":"ac-03.04_odp.02","label":"discretionary access control policy"}],"objectives":[{"id":"ac-3.4_obj-1","label":"AC-03(04)[01]","text":"{{ insert: param, ac-03.04_odp.01 }} is enforced over the set of covered subjects specified in the policy;"},{"id":"ac-3.4_obj-2","label":"AC-03(04)[02]","text":"{{ insert: param, ac-03.04_odp.02 }} is enforced over the set of covered objects specified in the policy;"},{"id":"ac-3.4_obj.a","label":"AC-03(04)(a)","text":"{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can pass the information to any other subjects or objects;"},{"id":"ac-3.4_obj.b","label":"AC-03(04)(b)","text":"{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can grant its privileges to other subjects;"},{"id":"ac-3.4_obj.c","label":"AC-03(04)(c)","text":"{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can change security attributes on subjects, objects, the system, or the system’s components;"},{"id":"ac-3.4_obj.d","label":"AC-03(04)(d)","text":"{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can choose the security attributes to be associated with newly created or revised objects;"},{"id":"ac-3.4_obj.e","label":"AC-03(04)(e)","text":"{{ insert: param, ac-03.04_odp.01 }} and {{ insert: param, ac-03.04_odp.02 }} are enforced where the policy specifies that a subject that has been granted access to information can change the rules governing access control."}],"methods":[{"method":"examine","label":"AC-03(04)-Examine"},{"method":"interview","label":"AC-03(04)-Interview"},{"method":"test","label":"AC-03(04)-Test"}],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(5)","oscal_id":"ac-3.5","family":"AC","title":"Security-relevant Information","statement":"Prevent access to <security-relevant information> except during secure, non-operable system states.","supplemental_guidance":"Security-relevant information is information within systems that can potentially impact the operation of security functions or the provision of security services in a manner that could result in failure to enforce system security and privacy policies or maintain the separation of code and data. Security-relevant information includes access control lists, filtering rules for routers or firewalls, configuration parameters for security services, and cryptographic key management information. Secure, non-operable system states include the times in which systems are not performing mission or business-related processing, such as when the system is offline for maintenance, boot-up, troubleshooting, or shut down.","implementation_level":"system","parameters":[{"id":"ac-03.05_odp","label":"security-relevant information"}],"methods":[{"method":"examine","label":"AC-03(05)-Examine"},{"method":"interview","label":"AC-03(05)-Interview"},{"method":"test","label":"AC-03(05)-Test"}],"related_controls":["CM-6","SC-39"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(6)","oscal_id":"ac-3.6","family":"AC","title":"Protection of User and System Information","statement":"","is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(7)","oscal_id":"ac-3.7","family":"AC","title":"Role-based Access Control","statement":"Enforce a role-based access control policy over defined subjects and objects and control access based upon <organization-defined roles and users authorized to assume such roles>.","supplemental_guidance":"Role-based access control (RBAC) is an access control policy that enforces access to objects and system functions based on the defined role (i.e., job function) of the subject. Organizations can create specific roles based on job functions and the authorizations (i.e., privileges) to perform needed operations on the systems associated with the organization-defined roles. When users are assigned to specific roles, they inherit the authorizations or privileges defined for those roles. RBAC simplifies privilege administration for organizations because privileges are not assigned directly to every user (which can be a large number of individuals) but are instead acquired through role assignments. RBAC can also increase privacy and security risk if individuals assigned to a role are given access to information beyond what they need to support organizational missions or business functions. RBAC can be implemented as a mandatory or discretionary form of access control. For organizations implementing RBAC with mandatory access controls, the requirements in [AC-3(3)](#ac-3.3) define the scope of the subjects and objects covered by the policy.","implementation_level":"organization","parameters":[{"id":"ac-3.7_prm_1","label":"organization-defined roles and users authorized to assume such roles"},{"id":"ac-03.07_odp.01","label":"roles"},{"id":"ac-03.07_odp.02","label":"users authorized to assume such roles"}],"objectives":[{"id":"ac-3.7_obj-1","label":"AC-03(07)[01]","text":"a role-based access control policy is enforced over defined subjects;"},{"id":"ac-3.7_obj-2","label":"AC-03(07)[02]","text":"a role-based access control policy is enforced over defined objects;"},{"id":"ac-3.7_obj-3","label":"AC-03(07)[03]","text":"access is controlled based on {{ insert: param, ac-03.07_odp.01 }} and {{ insert: param, ac-03.07_odp.02 }}."}],"methods":[{"method":"examine","label":"AC-03(07)-Examine"},{"method":"interview","label":"AC-03(07)-Interview"},{"method":"test","label":"AC-03(07)-Test"}],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(8)","oscal_id":"ac-3.8","family":"AC","title":"Revocation of Access Authorizations","statement":"Enforce the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on <rules>.","supplemental_guidance":"Revocation of access rules may differ based on the types of access revoked. For example, if a subject (i.e., user or process acting on behalf of a user) is removed from a group, access may not be revoked until the next time the object is opened or the next time the subject attempts to access the object. Revocation based on changes to security labels may take effect immediately. Organizations provide alternative approaches on how to make revocations immediate if systems cannot provide such capability and immediate revocation is necessary.","implementation_level":"organization","parameters":[{"id":"ac-03.08_odp","label":"rules"}],"objectives":[{"id":"ac-3.8_obj-1","label":"AC-03(08)[01]","text":"revocation of access authorizations is enforced, resulting from changes to the security attributes of subjects based on {{ insert: param, ac-03.08_odp }};"},{"id":"ac-3.8_obj-2","label":"AC-03(08)[02]","text":"revocation of access authorizations is enforced resulting from changes to the security attributes of objects based on {{ insert: param, ac-03.08_odp }}."}],"methods":[{"method":"examine","label":"AC-03(08)-Examine"},{"method":"interview","label":"AC-03(08)-Interview"},{"method":"test","label":"AC-03(08)-Test"}],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(9)","oscal_id":"ac-3.9","family":"AC","title":"Controlled Release","statement":"Release information outside of the system only if:\n(a) The receiving <system or system component> provides <controls> ; and\n(b) <controls> are used to validate the appropriateness of the information designated for release.","supplemental_guidance":"Organizations can only directly protect information when it resides within the system. Additional controls may be needed to ensure that organizational information is adequately protected once it is transmitted outside of the system. In situations where the system is unable to determine the adequacy of the protections provided by external entities, as a mitigation measure, organizations procedurally determine whether the external systems are providing adequate controls. The means used to determine the adequacy of controls provided by external systems include conducting periodic assessments (inspections/tests), establishing agreements between the organization and its counterpart organizations, or some other process. The means used by external entities to protect the information received need not be the same as those used by the organization, but the means employed are sufficient to provide consistent adjudication of the security and privacy policy to protect the information and individuals’ privacy.\n\nControlled release of information requires systems to implement technical or procedural means to validate the information prior to releasing it to external systems. For example, if the system passes information to a system controlled by another organization, technical means are employed to validate that the security and privacy attributes associated with the exported information are appropriate for the receiving system. Alternatively, if the system passes information to a printer in organization-controlled space, procedural means can be employed to ensure that only authorized individuals gain access to the printer.","implementation_level":"organization","parameters":[{"id":"ac-03.09_odp.01","label":"system or system component"},{"id":"ac-03.09_odp.02","label":"controls"},{"id":"ac-03.09_odp.03","label":"controls"}],"objectives":[{"id":"ac-3.9_obj.a","label":"AC-03(09)(a)","text":"information is released outside of the system only if the receiving {{ insert: param, ac-03.09_odp.01 }} provides {{ insert: param, ac-03.09_odp.02 }};"},{"id":"ac-3.9_obj.b","label":"AC-03(09)(b)","text":"information is released outside of the system only if {{ insert: param, ac-03.09_odp.03 }} are used to validate the appropriateness of the information designated for release."}],"methods":[{"method":"examine","label":"AC-03(09)-Examine"},{"method":"interview","label":"AC-03(09)-Interview"},{"method":"test","label":"AC-03(09)-Test"}],"related_controls":["CA-3","PT-7","PT-8","SA-9","SC-16"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(10)","oscal_id":"ac-3.10","family":"AC","title":"Audited Override of Access Control Mechanisms","statement":"Employ an audited override of automated access control mechanisms under <conditions> by <roles>.","supplemental_guidance":"In certain situations, such as when there is a threat to human life or an event that threatens the organization’s ability to carry out critical missions or business functions, an override capability for access control mechanisms may be needed. Override conditions are defined by organizations and used only in those limited circumstances. Audit events are defined in [AU-2](#au-2) . Audit records are generated in [AU-12](#au-12).","implementation_level":"organization","parameters":[{"id":"ac-03.10_odp.01","label":"conditions"},{"id":"ac-03.10_odp.02","label":"roles"}],"methods":[{"method":"examine","label":"AC-03(10)-Examine"},{"method":"interview","label":"AC-03(10)-Interview"},{"method":"test","label":"AC-03(10)-Test"}],"related_controls":["AU-2","AU-6","AU-10","AU-12","AU-14"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(11)","oscal_id":"ac-3.11","family":"AC","title":"Restrict Access to Specific Information Types","statement":"Restrict access to data repositories containing <information types>.","supplemental_guidance":"Restricting access to specific information is intended to provide flexibility regarding access control of specific information types within a system. For example, role-based access could be employed to allow access to only a specific type of personally identifiable information within a database rather than allowing access to the database in its entirety. Other examples include restricting access to cryptographic keys, authentication information, and selected system information.","implementation_level":"system","parameters":[{"id":"ac-03.11_odp","label":"information types"}],"methods":[{"method":"examine","label":"AC-03(11)-Examine"},{"method":"interview","label":"AC-03(11)-Interview"},{"method":"test","label":"AC-03(11)-Test"}],"related_controls":["CM-8","CM-12","CM-13","PM-5"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(12)","oscal_id":"ac-3.12","family":"AC","title":"Assert and Enforce Application Access","statement":"(a) Require applications to assert, as part of the installation process, the access needed to the following system applications and functions: <system applications and functions>;\n(b) Provide an enforcement mechanism to prevent unauthorized access; and\n(c) Approve access changes after initial installation of the application.","supplemental_guidance":"Asserting and enforcing application access is intended to address applications that need to access existing system applications and functions, including user contacts, global positioning systems, cameras, keyboards, microphones, networks, phones, or other files.","implementation_level":"system","parameters":[{"id":"ac-03.12_odp","label":"system applications and functions"}],"objectives":[{"id":"ac-3.12_obj.a","label":"AC-03(12)(a)","text":"as part of the installation process, applications are required to assert the access needed to the following system applications and functions: {{ insert: param, ac-03.12_odp }};"},{"id":"ac-3.12_obj.b","label":"AC-03(12)(b)","text":"an enforcement mechanism to prevent unauthorized access is provided;"},{"id":"ac-3.12_obj.c","label":"AC-03(12)(c)","text":"access changes after initial installation of the application are approved."}],"methods":[{"method":"examine","label":"AC-03(12)-Examine"},{"method":"interview","label":"AC-03(12)-Interview"},{"method":"test","label":"AC-03(12)-Test"}],"related_controls":["CM-7"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(13)","oscal_id":"ac-3.13","family":"AC","title":"Attribute-based Access Control","statement":"Enforce attribute-based access control policy over defined subjects and objects and control access based upon <attributes>.","supplemental_guidance":"Attribute-based access control is an access control policy that restricts system access to authorized users based on specified organizational attributes (e.g., job function, identity), action attributes (e.g., read, write, delete), environmental attributes (e.g., time of day, location), and resource attributes (e.g., classification of a document). Organizations can create rules based on attributes and the authorizations (i.e., privileges) to perform needed operations on the systems associated with organization-defined attributes and rules. When users are assigned to attributes defined in attribute-based access control policies or rules, they can be provisioned to a system with the appropriate privileges or dynamically granted access to a protected resource. Attribute-based access control can be implemented as either a mandatory or discretionary form of access control. When implemented with mandatory access controls, the requirements in [AC-3(3)](#ac-3.3) define the scope of the subjects and objects covered by the policy.","implementation_level":"system","parameters":[{"id":"ac-03.13_odp","label":"attributes"}],"objectives":[{"id":"ac-3.13_obj-1","label":"AC-03(13)[01]","text":"the attribute-based access control policy is enforced over defined subjects;"},{"id":"ac-3.13_obj-2","label":"AC-03(13)[02]","text":"the attribute-based access control policy is enforced over defined objects;"},{"id":"ac-3.13_obj-3","label":"AC-03(13)[03]","text":"access is controlled based on {{ insert: param, ac-03.13_odp }}."}],"methods":[{"method":"examine","label":"AC-03(13)-Examine"},{"method":"interview","label":"AC-03(13)-Interview"},{"method":"test","label":"AC-03(13)-Test"}],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(14)","oscal_id":"ac-3.14","family":"AC","title":"Individual Access","statement":"Provide <mechanisms> to enable individuals to have access to the following elements of their personally identifiable information: <elements>.","supplemental_guidance":"Individual access affords individuals the ability to review personally identifiable information about them held within organizational records, regardless of format. Access helps individuals to develop an understanding about how their personally identifiable information is being processed. It can also help individuals ensure that their data is accurate. Access mechanisms can include request forms and application interfaces. For federal agencies, [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) processes can be located in systems of record notices and on agency websites. Access to certain types of records may not be appropriate (e.g., for federal agencies, law enforcement records within a system of records may be exempt from disclosure under the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) ) or may require certain levels of authentication assurance. Organizational personnel consult with the senior agency official for privacy and legal counsel to determine appropriate mechanisms and access rights or limitations.","implementation_level":"system","parameters":[{"id":"ac-03.14_odp.01","label":"mechanisms"},{"id":"ac-03.14_odp.02","label":"elements"}],"methods":[{"method":"examine","label":"AC-03(14)-Examine"},{"method":"interview","label":"AC-03(14)-Interview"},{"method":"test","label":"AC-03(14)-Test"}],"related_controls":["IA-8","PM-22","PM-20","PM-21","PT-6"],"is_enhancement":true,"parent_id":"AC-3"},{"id":"AC-3(15)","oscal_id":"ac-3.15","family":"AC","title":"Discretionary and Mandatory Access Control","statement":"(a) Enforce <organization-defined mandatory access control policy> over the set of covered subjects and objects specified in the policy; and\n(b) Enforce <organization-defined discretionary access control policy> over the set of covered subjects and objects specified in the policy.","supplemental_guidance":"Simultaneously implementing a mandatory access control policy and a discretionary access control policy can provide additional protection against the unauthorized execution of code by users or processes acting on behalf of users. This helps prevent a single compromised user or process from compromising the entire system.","implementation_level":"system","parameters":[{"id":"ac-3.15_prm_1","label":"organization-defined mandatory access control policy"},{"id":"ac-3.15_prm_2","label":"organization-defined discretionary access control policy"},{"id":"ac-03.15_odp.01","label":"mandatory access control policy"},{"id":"ac-03.15_odp.02","label":"mandatory access control policy"},{"id":"ac-03.15_odp.03","label":"discretionary access control policy"},{"id":"ac-03.15_odp.04","label":"discretionary access control policy"}],"objectives":[{"id":"ac-3.15_obj.a-1","label":"AC-03(15)(a)[01]","text":"{{ insert: param, ac-03.15_odp.01 }} is enforced over the set of covered subjects specified in the policy;"},{"id":"ac-3.15_obj.a-2","label":"AC-03(15)(a)[02]","text":"{{ insert: param, ac-03.15_odp.02 }} is enforced over the set of covered objects specified in the policy;"},{"id":"ac-3.15_obj.b-1","label":"AC-03(15)(b)[01]","text":"{{ insert: param, ac-03.15_odp.03 }} is enforced over the set of covered subjects specified in the policy;"},{"id":"ac-3.15_obj.b-2","label":"AC-03(15)(b)[02]","text":"{{ insert: param, ac-03.15_odp.04 }} is enforced over the set of covered objects specified in the policy."}],"methods":[{"method":"examine","label":"AC-03(15)-Examine"},{"method":"interview","label":"AC-03(15)-Interview"},{"method":"test","label":"AC-03(15)-Test"}],"related_controls":["SC-2","SC-3","AC-4"],"is_enhancement":true,"parent_id":"AC-3"}]},{"id":"AC-4","oscal_id":"ac-4","family":"AC","title":"Information Flow Enforcement","statement":"Enforce approved authorizations for controlling the flow of information within the system and between connected systems based on <information flow control policies>.","supplemental_guidance":"Information flow control regulates where information can travel within a system and between systems (in contrast to who is allowed to access the information) and without regard to subsequent accesses to that information. Flow control restrictions include blocking external traffic that claims to be from within the organization, keeping export-controlled information from being transmitted in the clear to the Internet, restricting web requests that are not from the internal web proxy server, and limiting information transfers between organizations based on data structures and content. Transferring information between organizations may require an agreement specifying how the information flow is enforced (see [CA-3](#ca-3) ). Transferring information between systems in different security or privacy domains with different security or privacy policies introduces the risk that such transfers violate one or more domain security or privacy policies. In such situations, information owners/stewards provide guidance at designated policy enforcement points between connected systems. Organizations consider mandating specific architectural solutions to enforce specific security and privacy policies. Enforcement includes prohibiting information transfers between connected systems (i.e., allowing access only), verifying write permissions before accepting information from another security or privacy domain or connected system, employing hardware mechanisms to enforce one-way information flows, and implementing trustworthy regrading mechanisms to reassign security or privacy attributes and labels.\n\nOrganizations commonly employ information flow control policies and enforcement mechanisms to control the flow of information between designated sources and destinations within systems and between connected systems. Flow control is based on the characteristics of the information and/or the information path. Enforcement occurs, for example, in boundary protection devices that employ rule sets or establish configuration settings that restrict system services, provide a packet-filtering capability based on header information, or provide a message-filtering capability based on message content. Organizations also consider the trustworthiness of filtering and/or inspection mechanisms (i.e., hardware, firmware, and software components) that are critical to information flow enforcement. Control enhancements 3 through 32 primarily address cross-domain solution needs that focus on more advanced filtering techniques, in-depth analysis, and stronger flow enforcement mechanisms implemented in cross-domain products, such as high-assurance guards. Such capabilities are generally not available in commercial off-the-shelf products. Information flow enforcement also applies to control plane traffic (e.g., routing and DNS).","implementation_level":"system","parameters":[{"id":"ac-04_odp","label":"information flow control policies"}],"methods":[{"method":"examine","label":"AC-04-Examine"},{"method":"interview","label":"AC-04-Interview"},{"method":"test","label":"AC-04-Test"}],"references":[{"title":"SP 800-160-1"},{"title":"SP 800-162"},{"title":"SP 800-178"},{"title":"IR 8112"}],"related_controls":["AC-3","AC-6","AC-16","AC-17","AC-19","AC-21","AU-10","CA-3","CA-9","CM-7","PL-9","PM-24","SA-17","SC-4","SC-7","SC-16","SC-31"],"enhancements":[{"id":"AC-4(1)","oscal_id":"ac-4.1","family":"AC","title":"Object Security and Privacy Attributes","statement":"Use <organization-defined security and privacy attributes> associated with <organization-defined information, source, and destination objects> to enforce <information flow control policies> as a basis for flow control decisions.","supplemental_guidance":"Information flow enforcement mechanisms compare security and privacy attributes associated with information (i.e., data content and structure) and source and destination objects and respond appropriately when the enforcement mechanisms encounter information flows not explicitly allowed by information flow policies. For example, an information object labeled Secret would be allowed to flow to a destination object labeled Secret, but an information object labeled Top Secret would not be allowed to flow to a destination object labeled Secret. A dataset of personally identifiable information may be tagged with restrictions against combining with other types of datasets and, thus, would not be allowed to flow to the restricted dataset. Security and privacy attributes can also include source and destination addresses employed in traffic filter firewalls. Flow enforcement using explicit security or privacy attributes can be used, for example, to control the release of certain types of information.","implementation_level":"system","parameters":[{"id":"ac-4.1_prm_1","label":"organization-defined security and privacy attributes"},{"id":"ac-4.1_prm_2","label":"organization-defined information, source, and destination objects"},{"id":"ac-04.01_odp.01","label":"security attributes"},{"id":"ac-04.01_odp.02","label":"privacy attributes"},{"id":"ac-04.01_odp.03","label":"information objects"},{"id":"ac-04.01_odp.04","label":"information objects"},{"id":"ac-04.01_odp.05","label":"source objects"},{"id":"ac-04.01_odp.06","label":"source objects"},{"id":"ac-04.01_odp.07","label":"destination objects"},{"id":"ac-04.01_odp.08","label":"destination objects"},{"id":"ac-04.01_odp.09","label":"information flow control policies"}],"objectives":[{"id":"ac-4.1_obj-1","label":"AC-04(01)[01]","text":"{{ insert: param, ac-04.01_odp.01 }} associated with {{ insert: param, ac-04.01_odp.03 }}, {{ insert: param, ac-04.01_odp.05 }} , and {{ insert: param, ac-04.01_odp.07 }} are used to enforce {{ insert: param, ac-04.01_odp.09 }} as a basis for flow control decisions;"},{"id":"ac-4.1_obj-2","label":"AC-04(01)[02]","text":"{{ insert: param, ac-04.01_odp.02 }} associated with {{ insert: param, ac-04.01_odp.04 }}, {{ insert: param, ac-04.01_odp.06 }} , and {{ insert: param, ac-04.01_odp.08 }} are used to enforce {{ insert: param, ac-04.01_odp.09 }} as a basis for flow control decisions."}],"methods":[{"method":"examine","label":"AC-04(01)-Examine"},{"method":"interview","label":"AC-04(01)-Interview"},{"method":"test","label":"AC-04(01)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(2)","oscal_id":"ac-4.2","family":"AC","title":"Processing Domains","statement":"Use protected processing domains to enforce <information flow control policies> as a basis for flow control decisions.","supplemental_guidance":"Protected processing domains within systems are processing spaces that have controlled interactions with other processing spaces, enabling control of information flows between these spaces and to/from information objects. A protected processing domain can be provided, for example, by implementing domain and type enforcement. In domain and type enforcement, system processes are assigned to domains, information is identified by types, and information flows are controlled based on allowed information accesses (i.e., determined by domain and type), allowed signaling among domains, and allowed process transitions to other domains.","implementation_level":"system","parameters":[{"id":"ac-04.02_odp","label":"information flow control policies"}],"methods":[{"method":"examine","label":"AC-04(02)-Examine"},{"method":"interview","label":"AC-04(02)-Interview"},{"method":"test","label":"AC-04(02)-Test"}],"related_controls":["SC-39"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(3)","oscal_id":"ac-4.3","family":"AC","title":"Dynamic Information Flow Control","statement":"Enforce <information flow control policies>.","supplemental_guidance":"Organizational policies regarding dynamic information flow control include allowing or disallowing information flows based on changing conditions or mission or operational considerations. Changing conditions include changes in risk tolerance due to changes in the immediacy of mission or business needs, changes in the threat environment, and detection of potentially harmful or adverse events.","implementation_level":"system","parameters":[{"id":"ac-04.03_odp","label":"information flow control policies"}],"methods":[{"method":"examine","label":"AC-04(03)-Examine"},{"method":"interview","label":"AC-04(03)-Interview"},{"method":"test","label":"AC-04(03)-Test"}],"related_controls":["SI-4"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(4)","oscal_id":"ac-4.4","family":"AC","title":"Flow Control of Encrypted Information","statement":"Prevent encrypted information from bypassing <information flow control mechanisms> by <organization-defined parameter>.","supplemental_guidance":"Flow control mechanisms include content checking, security policy filters, and data type identifiers. The term encryption is extended to cover encoded data not recognized by filtering mechanisms.","implementation_level":"system","parameters":[{"id":"ac-04.04_odp.01","label":"information flow control mechanisms"},{"id":"ac-04.04_odp.02","label":"","choices":["decrypting the information","blocking the flow of the encrypted information","terminating communications sessions attempting to pass encrypted information","{{ insert: param, ac-04.04_odp.03 }} "],"how_many":"one-or-more"},{"id":"ac-04.04_odp.03","label":"organization-defined procedure or method"}],"methods":[{"method":"examine","label":"AC-04(04)-Examine"},{"method":"interview","label":"AC-04(04)-Interview"},{"method":"test","label":"AC-04(04)-Test"}],"related_controls":["SI-4"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(5)","oscal_id":"ac-4.5","family":"AC","title":"Embedded Data Types","statement":"Enforce <limitations> on embedding data types within other data types.","supplemental_guidance":"Embedding data types within other data types may result in reduced flow control effectiveness. Data type embedding includes inserting files as objects within other files and using compressed or archived data types that may include multiple embedded data types. Limitations on data type embedding consider the levels of embedding and prohibit levels of data type embedding that are beyond the capability of the inspection tools.","implementation_level":"system","parameters":[{"id":"ac-04.05_odp","label":"limitations"}],"methods":[{"method":"examine","label":"AC-04(05)-Examine"},{"method":"interview","label":"AC-04(05)-Interview"},{"method":"test","label":"AC-04(05)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(6)","oscal_id":"ac-4.6","family":"AC","title":"Metadata","statement":"Enforce information flow control based on <metadata>.","supplemental_guidance":"Metadata is information that describes the characteristics of data. Metadata can include structural metadata describing data structures or descriptive metadata describing data content. Enforcement of allowed information flows based on metadata enables simpler and more effective flow control. Organizations consider the trustworthiness of metadata regarding data accuracy (i.e., knowledge that the metadata values are correct with respect to the data), data integrity (i.e., protecting against unauthorized changes to metadata tags), and the binding of metadata to the data payload (i.e., employing sufficiently strong binding techniques with appropriate assurance).","implementation_level":"system","parameters":[{"id":"ac-04.06_odp","label":"metadata"}],"methods":[{"method":"examine","label":"AC-04(06)-Examine"},{"method":"interview","label":"AC-04(06)-Interview"},{"method":"test","label":"AC-04(06)-Test"}],"related_controls":["AC-16","SI-7"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(7)","oscal_id":"ac-4.7","family":"AC","title":"One-way Flow Mechanisms","statement":"Enforce one-way information flows through hardware-based flow control mechanisms.","supplemental_guidance":"One-way flow mechanisms may also be referred to as a unidirectional network, unidirectional security gateway, or data diode. One-way flow mechanisms can be used to prevent data from being exported from a higher impact or classified domain or system while permitting data from a lower impact or unclassified domain or system to be imported.","implementation_level":"system","methods":[{"method":"examine","label":"AC-04(07)-Examine"},{"method":"interview","label":"AC-04(07)-Interview"},{"method":"test","label":"AC-04(07)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(8)","oscal_id":"ac-4.8","family":"AC","title":"Security and Privacy Policy Filters","statement":"(a) Enforce information flow control using <organization-defined security or privacy policy filters> as a basis for flow control decisions for <organization-defined information flows> ; and\n(b) <organization-defined parameter> data after a filter processing failure in accordance with <organization-defined security or privacy policy>.","supplemental_guidance":"Organization-defined security or privacy policy filters can address data structures and content. For example, security or privacy policy filters for data structures can check for maximum file lengths, maximum field sizes, and data/file types (for structured and unstructured data). Security or privacy policy filters for data content can check for specific words, enumerated values or data value ranges, and hidden content. Structured data permits the interpretation of data content by applications. Unstructured data refers to digital information without a data structure or with a data structure that does not facilitate the development of rule sets to address the impact or classification level of the information conveyed by the data or the flow enforcement decisions. Unstructured data consists of bitmap objects that are inherently non-language-based (i.e., image, video, or audio files) and textual objects that are based on written or printed languages. Organizations can implement more than one security or privacy policy filter to meet information flow control objectives.","implementation_level":"system","parameters":[{"id":"ac-4.8_prm_1","label":"organization-defined security or privacy policy filters"},{"id":"ac-4.8_prm_2","label":"organization-defined information flows"},{"id":"ac-4.8_prm_4","label":"organization-defined security or privacy policy"},{"id":"ac-04.08_odp.01","label":"security policy filter"},{"id":"ac-04.08_odp.02","label":"privacy policy filter"},{"id":"ac-04.08_odp.03","label":"information flows"},{"id":"ac-04.08_odp.04","label":"information flows"},{"id":"ac-04.08_odp.05","label":"","choices":["block","strip","modify","quarantine"],"how_many":"one-or-more"},{"id":"ac-04.08_odp.06","label":"security policy"},{"id":"ac-04.08_odp.07","label":"privacy policy"}],"objectives":[{"id":"ac-4.8_obj.a-1","label":"AC-04(08)(a)[01]","text":"information flow control is enforced using {{ insert: param, ac-04.08_odp.01 }} as a basis for flow control decisions for {{ insert: param, ac-04.08_odp.03 }};"},{"id":"ac-4.8_obj.a-2","label":"AC-04(08)(a)[02]","text":"information flow control is enforced using {{ insert: param, ac-04.08_odp.02 }} as a basis for flow control decisions for {{ insert: param, ac-04.08_odp.04 }};"},{"id":"ac-4.8_obj.b","label":"AC-04(08)(b)","text":"{{ insert: param, ac-04.08_odp.05 }} data after a filter processing failure in accordance with {{ insert: param, ac-04.08_odp.06 }};\n\n{{ insert: param, ac-04.08_odp.05 }} data after a filter processing failure in accordance with {{ insert: param, ac-04.08_odp.07 }}."}],"methods":[{"method":"examine","label":"AC-04(08)-Examine"},{"method":"interview","label":"AC-04(08)-Interview"},{"method":"test","label":"AC-04(08)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(9)","oscal_id":"ac-4.9","family":"AC","title":"Human Reviews","statement":"Enforce the use of human reviews for <information flows> under the following conditions: <conditions>.","supplemental_guidance":"Organizations define security or privacy policy filters for all situations where automated flow control decisions are possible. When a fully automated flow control decision is not possible, then a human review may be employed in lieu of or as a complement to automated security or privacy policy filtering. Human reviews may also be employed as deemed necessary by organizations.","implementation_level":"organization","parameters":[{"id":"ac-04.09_odp.01","label":"information flows"},{"id":"ac-04.09_odp.02","label":"conditions"}],"methods":[{"method":"examine","label":"AC-04(09)-Examine"},{"method":"interview","label":"AC-04(09)-Interview"},{"method":"test","label":"AC-04(09)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(10)","oscal_id":"ac-4.10","family":"AC","title":"Enable and Disable Security or Privacy Policy Filters","statement":"Provide the capability for privileged administrators to enable and disable <organization-defined security or privacy policy filters> under the following conditions: <organization-defined conditions>.","supplemental_guidance":"For example, as allowed by the system authorization, administrators can enable security or privacy policy filters to accommodate approved data types. Administrators also have the capability to select the filters that are executed on a specific data flow based on the type of data that is being transferred, the source and destination security domains, and other security or privacy relevant features, as needed.","implementation_level":"system","parameters":[{"id":"ac-4.10_prm_1","label":"organization-defined security or privacy policy filters"},{"id":"ac-4.10_prm_2","label":"organization-defined conditions"},{"id":"ac-04.10_odp.01","label":"security filters"},{"id":"ac-04.10_odp.02","label":"privacy filters"},{"id":"ac-04.10_odp.03","label":"conditions"},{"id":"ac-04.10_odp.04","label":"conditions"}],"objectives":[{"id":"ac-4.10_obj-1","label":"AC-04(10)[01]","text":"capability is provided for privileged administrators to enable and disable {{ insert: param, ac-04.10_odp.01 }} under {{ insert: param, ac-04.10_odp.03 }};"},{"id":"ac-4.10_obj-2","label":"AC-04(10)[02]","text":"capability is provided for privileged administrators to enable and disable {{ insert: param, ac-04.10_odp.02 }} under {{ insert: param, ac-04.10_odp.04 }}."}],"methods":[{"method":"examine","label":"AC-04(10)-Examine"},{"method":"interview","label":"AC-04(10)-Interview"},{"method":"test","label":"AC-04(10)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(11)","oscal_id":"ac-4.11","family":"AC","title":"Configuration of Security or Privacy Policy Filters","statement":"Provide the capability for privileged administrators to configure <organization-defined security or privacy policy filters> to support different security or privacy policies.","supplemental_guidance":"Documentation contains detailed information for configuring security or privacy policy filters. For example, administrators can configure security or privacy policy filters to include the list of inappropriate words that security or privacy policy mechanisms check in accordance with the definitions provided by organizations.","implementation_level":"system","parameters":[{"id":"ac-4.11_prm_1","label":"organization-defined security or privacy policy filters"},{"id":"ac-04.11_odp.01","label":"security policy filters"},{"id":"ac-04.11_odp.02","label":"privacy policy filters"}],"objectives":[{"id":"ac-4.11_obj-1","label":"AC-04(11)[01]","text":"capability is provided for privileged administrators to configure {{ insert: param, ac-04.11_odp.01 }} to support different security or privacy policies;"},{"id":"ac-4.11_obj-2","label":"AC-04(11)[02]","text":"capability is provided for privileged administrators to configure {{ insert: param, ac-04.11_odp.02 }} to support different security or privacy policies."}],"methods":[{"method":"examine","label":"AC-04(11)-Examine"},{"method":"interview","label":"AC-04(11)-Interview"},{"method":"test","label":"AC-04(11)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(12)","oscal_id":"ac-4.12","family":"AC","title":"Data Type Identifiers","statement":"When transferring information between different security domains, use <data type identifiers> to validate data essential for information flow decisions.","supplemental_guidance":"Data type identifiers include filenames, file types, file signatures or tokens, and multiple internal file signatures or tokens. Systems only allow transfer of data that is compliant with data type format specifications. Identification and validation of data types is based on defined specifications associated with each allowed data format. The filename and number alone are not used for data type identification. Content is validated syntactically and semantically against its specification to ensure that it is the proper data type.","implementation_level":"system","parameters":[{"id":"ac-04.12_odp","label":"data type identifiers"}],"methods":[{"method":"examine","label":"AC-04(12)-Examine"},{"method":"interview","label":"AC-04(12)-Interview"},{"method":"test","label":"AC-04(12)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(13)","oscal_id":"ac-4.13","family":"AC","title":"Decomposition into Policy-relevant Subcomponents","statement":"When transferring information between different security domains, decompose information into <policy-relevant subcomponents> for submission to policy enforcement mechanisms.","supplemental_guidance":"Decomposing information into policy-relevant subcomponents prior to information transfer facilitates policy decisions on source, destination, certificates, classification, attachments, and other security- or privacy-related component differentiators. Policy enforcement mechanisms apply filtering, inspection, and/or sanitization rules to the policy-relevant subcomponents of information to facilitate flow enforcement prior to transferring such information to different security domains.","implementation_level":"system","parameters":[{"id":"ac-04.13_odp","label":"policy-relevant subcomponents"}],"methods":[{"method":"examine","label":"AC-04(13)-Examine"},{"method":"interview","label":"AC-04(13)-Interview"},{"method":"test","label":"AC-04(13)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(14)","oscal_id":"ac-4.14","family":"AC","title":"Security or Privacy Policy Filter Constraints","statement":"When transferring information between different security domains, implement <organization-defined security or privacy policy filters> requiring fully enumerated formats that restrict data structure and content.","supplemental_guidance":"Data structure and content restrictions reduce the range of potential malicious or unsanctioned content in cross-domain transactions. Security or privacy policy filters that restrict data structures include restricting file sizes and field lengths. Data content policy filters include encoding formats for character sets, restricting character data fields to only contain alpha-numeric characters, prohibiting special characters, and validating schema structures.","implementation_level":"system","parameters":[{"id":"ac-4.14_prm_1","label":"organization-defined security or privacy policy filters"},{"id":"ac-04.14_odp.01","label":"security policy filters"},{"id":"ac-04.14_odp.02","label":"privacy policy filters"}],"objectives":[{"id":"ac-4.14_obj-1","label":"AC-04(14)[01]","text":"when transferring information between different security domains, implemented {{ insert: param, ac-04.14_odp.01 }} require fully enumerated formats that restrict data structure and content;"},{"id":"ac-4.14_obj-2","label":"AC-04(14)[02]","text":"when transferring information between different security domains, implemented {{ insert: param, ac-04.14_odp.02 }} require fully enumerated formats that restrict data structure and content."}],"methods":[{"method":"examine","label":"AC-04(14)-Examine"},{"method":"interview","label":"AC-04(14)-Interview"},{"method":"test","label":"AC-04(14)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(15)","oscal_id":"ac-4.15","family":"AC","title":"Detection of Unsanctioned Information","statement":"When transferring information between different security domains, examine the information for the presence of <unsanctioned information> and prohibit the transfer of such information in accordance with the <organization-defined security or privacy policy>.","supplemental_guidance":"Unsanctioned information includes malicious code, information that is inappropriate for release from the source network, or executable code that could disrupt or harm the services or systems on the destination network.","implementation_level":"system","parameters":[{"id":"ac-4.15_prm_2","label":"organization-defined security or privacy policy"},{"id":"ac-04.15_odp.01","label":"unsanctioned information"},{"id":"ac-04.15_odp.02","label":"security policy"},{"id":"ac-04.15_odp.03","label":"privacy policy"}],"objectives":[{"id":"ac-4.15_obj-1","label":"AC-04(15)[01]","text":"when transferring information between different security domains, information is examined for the presence of {{ insert: param, ac-04.15_odp.01 }};"},{"id":"ac-4.15_obj-2","label":"AC-04(15)[02]","text":"when transferring information between different security domains, transfer of {{ insert: param, ac-04.15_odp.01 }} is prohibited in accordance with the {{ insert: param, ac-04.15_odp.02 }};"},{"id":"ac-4.15_obj-3","label":"AC-04(15)[03]","text":"when transferring information between different security domains, transfer of {{ insert: param, ac-04.15_odp.01 }} is prohibited in accordance with the {{ insert: param, ac-04.15_odp.03 }}."}],"methods":[{"method":"examine","label":"AC-04(15)-Examine"},{"method":"interview","label":"AC-04(15)-Interview"},{"method":"test","label":"AC-04(15)-Test"}],"related_controls":["SI-3"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(16)","oscal_id":"ac-4.16","family":"AC","title":"Information Transfers on Interconnected Systems","statement":"","is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(17)","oscal_id":"ac-4.17","family":"AC","title":"Domain Authentication","statement":"Uniquely identify and authenticate source and destination points by <organization-defined parameter> for information transfer.","supplemental_guidance":"Attribution is a critical component of a security and privacy concept of operations. The ability to identify source and destination points for information flowing within systems allows the forensic reconstruction of events and encourages policy compliance by attributing policy violations to specific organizations or individuals. Successful domain authentication requires that system labels distinguish among systems, organizations, and individuals involved in preparing, sending, receiving, or disseminating information. Attribution also allows organizations to better maintain the lineage of personally identifiable information processing as it flows through systems and can facilitate consent tracking, as well as correction, deletion, or access requests from individuals.","implementation_level":"system","parameters":[{"id":"ac-04.17_odp","label":"","choices":["organization, system, application, service, individual"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"AC-04(17)-Examine"},{"method":"interview","label":"AC-04(17)-Interview"},{"method":"test","label":"AC-04(17)-Test"}],"related_controls":["IA-2","IA-3","IA-9"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(18)","oscal_id":"ac-4.18","family":"AC","title":"Security Attribute Binding","statement":"","is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(19)","oscal_id":"ac-4.19","family":"AC","title":"Validation of Metadata","statement":"When transferring information between different security domains, implement <organization-defined security or privacy policy filters> on metadata.","supplemental_guidance":"All information (including metadata and the data to which the metadata applies) is subject to filtering and inspection. Some organizations distinguish between metadata and data payloads (i.e., only the data to which the metadata is bound). Other organizations do not make such distinctions and consider metadata and the data to which the metadata applies to be part of the payload.","implementation_level":"system","parameters":[{"id":"ac-4.19_prm_1","label":"organization-defined security or privacy policy filters"},{"id":"ac-04.19_odp.01","label":"security policy filters"},{"id":"ac-04.19_odp.02","label":"privacy policy filters"}],"objectives":[{"id":"ac-4.19_obj-1","label":"AC-04(19)[01]","text":"when transferring information between different security domains, {{ insert: param, ac-04.19_odp.01 }} are implemented on metadata;"},{"id":"ac-4.19_obj-2","label":"AC-04(19)[02]","text":"when transferring information between different security domains, {{ insert: param, ac-04.19_odp.02 }} are implemented on metadata."}],"methods":[{"method":"examine","label":"AC-04(19)-Examine"},{"method":"interview","label":"AC-04(19)-Interview"},{"method":"test","label":"AC-04(19)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(20)","oscal_id":"ac-4.20","family":"AC","title":"Approved Solutions","statement":"Employ <solutions in approved configurations> to control the flow of <information> across security domains.","supplemental_guidance":"Organizations define approved solutions and configurations in cross-domain policies and guidance in accordance with the types of information flows across classification boundaries. The National Security Agency (NSA) National Cross Domain Strategy and Management Office provides a listing of approved cross-domain solutions. Contact [ncdsmo@nsa.gov](mailto:ncdsmo@nsa.gov) for more information.","implementation_level":"organization","parameters":[{"id":"ac-04.20_odp.01","label":"solutions in approved configurations"},{"id":"ac-04.20_odp.02","label":"information"}],"methods":[{"method":"examine","label":"AC-04(20)-Examine"},{"method":"interview","label":"AC-04(20)-Interview"},{"method":"test","label":"AC-04(20)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(21)","oscal_id":"ac-4.21","family":"AC","title":"Physical or Logical Separation of Information Flows","statement":"Separate information flows logically or physically using <organization-defined mechanisms and/or techniques> to accomplish <required separations>.","supplemental_guidance":"Enforcing the separation of information flows associated with defined types of data can enhance protection by ensuring that information is not commingled while in transit and by enabling flow control by transmission paths that are not otherwise achievable. Types of separable information include inbound and outbound communications traffic, service requests and responses, and information of differing security impact or classification levels.","implementation_level":"organization","parameters":[{"id":"ac-4.21_prm_1","label":"organization-defined mechanisms and/or techniques"},{"id":"ac-04.21_odp.01","label":"mechanisms and/or techniques"},{"id":"ac-04.21_odp.02","label":"mechanisms and/or techniques"},{"id":"ac-04.21_odp.03","label":"required separations"}],"objectives":[{"id":"ac-4.21_obj-1","label":"AC-04(21)[01]","text":"information flows are separated logically using {{ insert: param, ac-04.21_odp.01 }} to accomplish {{ insert: param, ac-04.21_odp.03 }};"},{"id":"ac-4.21_obj-2","label":"AC-04(21)[02]","text":"information flows are separated physically using {{ insert: param, ac-04.21_odp.02 }} to accomplish {{ insert: param, ac-04.21_odp.03 }}."}],"methods":[{"method":"examine","label":"AC-04(21)-Examine"},{"method":"interview","label":"AC-04(21)-Interview"},{"method":"test","label":"AC-04(21)-Test"}],"related_controls":["SC-32"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(22)","oscal_id":"ac-4.22","family":"AC","title":"Access Only","statement":"Provide access from a single device to computing platforms, applications, or data residing in multiple different security domains, while preventing information flow between the different security domains.","supplemental_guidance":"The system provides a capability for users to access each connected security domain without providing any mechanisms to allow users to transfer data or information between the different security domains. An example of an access-only solution is a terminal that provides a user access to information with different security classifications while assuredly keeping the information separate.","implementation_level":"system","methods":[{"method":"examine","label":"AC-04(22)-Examine"},{"method":"interview","label":"AC-04(22)-Interview"},{"method":"test","label":"AC-04(22)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(23)","oscal_id":"ac-4.23","family":"AC","title":"Modify Non-releasable Information","statement":"When transferring information between different security domains, modify non-releasable information by implementing <modification action>.","supplemental_guidance":"Modifying non-releasable information can help prevent a data spill or attack when information is transferred across security domains. Modification actions include masking, permutation, alteration, removal, or redaction.","implementation_level":"organization","parameters":[{"id":"ac-04.23_odp","label":"modification action"}],"methods":[{"method":"examine","label":"AC-04(23)-Examine"},{"method":"interview","label":"AC-04(23)-Interview"},{"method":"test","label":"AC-04(23)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(24)","oscal_id":"ac-4.24","family":"AC","title":"Internal Normalized Format","statement":"When transferring information between different security domains, parse incoming data into an internal normalized format and regenerate the data to be consistent with its intended specification.","supplemental_guidance":"Converting data into normalized forms is one of most of effective mechanisms to stop malicious attacks and large classes of data exfiltration.","implementation_level":"system","objectives":[{"id":"ac-4.24_obj-1","label":"AC-04(24)[01]","text":"when transferring information between different security domains, incoming data is parsed into an internal, normalized format;"},{"id":"ac-4.24_obj-2","label":"AC-04(24)[02]","text":"when transferring information between different security domains, the data is regenerated to be consistent with its intended specification."}],"methods":[{"method":"examine","label":"AC-04(24)-Examine"},{"method":"interview","label":"AC-04(24)-Interview"},{"method":"test","label":"AC-04(24)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(25)","oscal_id":"ac-4.25","family":"AC","title":"Data Sanitization","statement":"When transferring information between different security domains, sanitize data to minimize <organization-defined parameter> in accordance with <policy>.","supplemental_guidance":"Data sanitization is the process of irreversibly removing or destroying data stored on a memory device (e.g., hard drives, flash memory/solid state drives, mobile devices, CDs, and DVDs) or in hard copy form.","implementation_level":"system","parameters":[{"id":"ac-04.25_odp.01","label":"","choices":["delivery of malicious content, command and control of malicious code, malicious code augmentation, and steganography-encoded data","spillage of sensitive information"],"how_many":"one-or-more"},{"id":"ac-04.25_odp.02","label":"policy"}],"methods":[{"method":"examine","label":"AC-04(25)-Examine"},{"method":"interview","label":"AC-04(25)-Interview"},{"method":"test","label":"AC-04(25)-Test"}],"related_controls":["MP-6"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(26)","oscal_id":"ac-4.26","family":"AC","title":"Audit Filtering Actions","statement":"When transferring information between different security domains, record and audit content filtering actions and results for the information being filtered.","supplemental_guidance":"Content filtering is the process of inspecting information as it traverses a cross-domain solution and determines if the information meets a predefined policy. Content filtering actions and the results of filtering actions are recorded for individual messages to ensure that the correct filter actions were applied. Content filter reports are used to assist in troubleshooting actions by, for example, determining why message content was modified and/or why it failed the filtering process. Audit events are defined in [AU-2](#au-2) . Audit records are generated in [AU-12](#au-12).","implementation_level":"organization","objectives":[{"id":"ac-4.26_obj-1","label":"AC-04(26)[01]","text":"when transferring information between different security domains, content-filtering actions are recorded and audited;"},{"id":"ac-4.26_obj-2","label":"AC-04(26)[02]","text":"when transferring information between different security domains, results for the information being filtered are recorded and audited."}],"methods":[{"method":"examine","label":"AC-04(26)-Examine"},{"method":"interview","label":"AC-04(26)-Interview"},{"method":"test","label":"AC-04(26)-Test"}],"related_controls":["AU-2","AU-3","AU-12"],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(27)","oscal_id":"ac-4.27","family":"AC","title":"Redundant/Independent Filtering Mechanisms","statement":"When transferring information between different security domains, implement content filtering solutions that provide redundant and independent filtering mechanisms for each data type.","supplemental_guidance":"Content filtering is the process of inspecting information as it traverses a cross-domain solution and determines if the information meets a predefined policy. Redundant and independent content filtering eliminates a single point of failure filtering system. Independence is defined as the implementation of a content filter that uses a different code base and supporting libraries (e.g., two JPEG filters using different vendors’ JPEG libraries) and multiple, independent system processes.","implementation_level":"system","methods":[{"method":"examine","label":"AC-04(27)-Examine"},{"method":"interview","label":"AC-04(27)-Interview"},{"method":"test","label":"AC-04(27)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(28)","oscal_id":"ac-4.28","family":"AC","title":"Linear Filter Pipelines","statement":"When transferring information between different security domains, implement a linear content filter pipeline that is enforced with discretionary and mandatory access controls.","supplemental_guidance":"Content filtering is the process of inspecting information as it traverses a cross-domain solution and determines if the information meets a predefined policy. The use of linear content filter pipelines ensures that filter processes are non-bypassable and always invoked. In general, the use of parallel filtering architectures for content filtering of a single data type introduces bypass and non-invocation issues.","implementation_level":"system","methods":[{"method":"examine","label":"AC-04(28)-Examine"},{"method":"interview","label":"AC-04(28)-Interview"},{"method":"test","label":"AC-04(28)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(29)","oscal_id":"ac-4.29","family":"AC","title":"Filter Orchestration Engines","statement":"When transferring information between different security domains, employ content filter orchestration engines to ensure that:\n(a) Content filtering mechanisms successfully complete execution without errors; and\n(b) Content filtering actions occur in the correct order and comply with <policy>.","supplemental_guidance":"Content filtering is the process of inspecting information as it traverses a cross-domain solution and determines if the information meets a predefined security policy. An orchestration engine coordinates the sequencing of activities (manual and automated) in a content filtering process. Errors are defined as either anomalous actions or unexpected termination of the content filter process. This is not the same as a filter failing content due to non-compliance with policy. Content filter reports are a commonly used mechanism to ensure that expected filtering actions are completed successfully.","implementation_level":"organization","parameters":[{"id":"ac-04.29_odp","label":"policy"}],"objectives":[{"id":"ac-4.29_obj.a","label":"AC-04(29)(a)","text":"when transferring information between security domains, content filter orchestration engines are employed to ensure that content-filtering mechanisms successfully complete execution without errors;"},{"id":"ac-4.29_obj.b-1","label":"AC-04(29)(b)[01]","text":"when transferring information between security domains, content filter orchestration engines are employed to ensure that content-filtering actions occur in the correct order;"},{"id":"ac-4.29_obj.b-2","label":"AC-04(29)(b)[02]","text":"when transferring information between security domains, content filter orchestration engines are employed to ensure that content-filtering actions comply with {{ insert: param, ac-04.29_odp }}."}],"methods":[{"method":"examine","label":"AC-04(29)-Examine"},{"method":"interview","label":"AC-04(29)-Interview"},{"method":"test","label":"AC-04(29)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(30)","oscal_id":"ac-4.30","family":"AC","title":"Filter Mechanisms Using Multiple Processes","statement":"When transferring information between different security domains, implement content filtering mechanisms using multiple processes.","supplemental_guidance":"The use of multiple processes to implement content filtering mechanisms reduces the likelihood of a single point of failure.","implementation_level":"system","methods":[{"method":"examine","label":"AC-04(30)-Examine"},{"method":"interview","label":"AC-04(30)-Interview"},{"method":"test","label":"AC-04(30)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(31)","oscal_id":"ac-4.31","family":"AC","title":"Failed Content Transfer Prevention","statement":"When transferring information between different security domains, prevent the transfer of failed content to the receiving domain.","supplemental_guidance":"Content that failed filtering checks can corrupt the system if transferred to the receiving domain.","implementation_level":"system","methods":[{"method":"examine","label":"AC-04(31)-Examine"},{"method":"interview","label":"AC-04(31)-Interview"},{"method":"test","label":"AC-04(31)-Test"}],"is_enhancement":true,"parent_id":"AC-4"},{"id":"AC-4(32)","oscal_id":"ac-4.32","family":"AC","title":"Process Requirements for Information Transfer","statement":"When transferring information between different security domains, the process that transfers information between filter pipelines:\n(a) Does not filter message content;\n(b) Validates filtering metadata;\n(c) Ensures the content associated with the filtering metadata has successfully completed filtering; and\n(d) Transfers the content to the destination filter pipeline.","supplemental_guidance":"The processes transferring information between filter pipelines have minimum complexity and functionality to provide assurance that the processes operate correctly.","implementation_level":"system","objectives":[{"id":"ac-4.32_obj.a","label":"AC-04(32)(a)","text":"when transferring information between different security domains, the process that transfers information between filter pipelines does not filter message content;"},{"id":"ac-4.32_obj.b","label":"AC-04(32)(b)","text":"when transferring information between different security domains, the process that transfers information between filter pipelines validates filtering metadata;"},{"id":"ac-4.32_obj.c","label":"AC-04(32)(c)","text":"when transferring information between different security domains, the process that transfers information between filter pipelines ensures that the content with the filtering metadata has successfully completed filtering;"},{"id":"ac-4.32_obj.d","label":"AC-04(32)(d)","text":"when transferring information between different security domains, the process that transfers information between filter pipelines transfers the content to the destination filter pipeline."}],"methods":[{"method":"examine","label":"AC-04(32)-Examine"},{"method":"interview","label":"AC-04(32)-Interview"},{"method":"test","label":"AC-04(32)-Test"}],"is_enhancement":true,"parent_id":"AC-4"}]},{"id":"AC-5","oscal_id":"ac-5","family":"AC","title":"Separation of Duties","statement":"a. Identify and document <duties of individuals> ; and\nb. Define system access authorizations to support separation of duties.","supplemental_guidance":"Separation of duties addresses the potential for abuse of authorized privileges and helps to reduce the risk of malevolent activity without collusion. Separation of duties includes dividing mission or business functions and support functions among different individuals or roles, conducting system support functions with different individuals, and ensuring that security personnel who administer access control functions do not also administer audit functions. Because separation of duty violations can span systems and application domains, organizations consider the entirety of systems and system components when developing policy on separation of duties. Separation of duties is enforced through the account management activities in [AC-2](#ac-2) , access control mechanisms in [AC-3](#ac-3) , and identity management activities in [IA-2](#ia-2), [IA-4](#ia-4) , and [IA-12](#ia-12).","implementation_level":"organization","parameters":[{"id":"ac-05_odp","label":"duties of individuals"}],"objectives":[{"id":"ac-5_obj.a","label":"AC-05a.","text":"{{ insert: param, ac-05_odp }} are identified and documented;"},{"id":"ac-5_obj.b","label":"AC-05b.","text":"system access authorizations to support separation of duties are defined."}],"methods":[{"method":"examine","label":"AC-05-Examine"},{"method":"interview","label":"AC-05-Interview"},{"method":"test","label":"AC-05-Test"}],"related_controls":["AC-2","AC-3","AC-6","AU-9","CM-5","CM-11","CP-9","IA-2","IA-4","IA-5","IA-12","MA-3","MA-5","PS-2","SA-8","SA-17"]},{"id":"AC-6","oscal_id":"ac-6","family":"AC","title":"Least Privilege","statement":"Employ the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks.","supplemental_guidance":"Organizations employ least privilege for specific duties and systems. The principle of least privilege is also applied to system processes, ensuring that the processes have access to systems and operate at privilege levels no higher than necessary to accomplish organizational missions or business functions. Organizations consider the creation of additional processes, roles, and accounts as necessary to achieve least privilege. Organizations apply least privilege to the development, implementation, and operation of organizational systems.","implementation_level":"organization","methods":[{"method":"examine","label":"AC-06-Examine"},{"method":"interview","label":"AC-06-Interview"},{"method":"test","label":"AC-06-Test"}],"related_controls":["AC-2","AC-3","AC-5","AC-16","CM-5","CM-11","PL-2","PM-12","SA-8","SA-15","SA-17","SC-38"],"enhancements":[{"id":"AC-6(1)","oscal_id":"ac-6.1","family":"AC","title":"Authorize Access to Security Functions","statement":"Authorize access for <individuals and roles> to:\n(a) <organization-defined security functions (deployed in hardware, software, and firmware)> ; and\n(b) <security-relevant information>.","supplemental_guidance":"Security functions include establishing system accounts, configuring access authorizations (i.e., permissions, privileges), configuring settings for events to be audited, and establishing intrusion detection parameters. Security-relevant information includes filtering rules for routers or firewalls, configuration parameters for security services, cryptographic key management information, and access control lists. Authorized personnel include security administrators, system administrators, system security officers, system programmers, and other privileged users.","implementation_level":"organization","parameters":[{"id":"ac-6.1_prm_2","label":"organization-defined security functions (deployed in hardware, software, and firmware)"},{"id":"ac-06.01_odp.01","label":"individuals and roles"},{"id":"ac-06.01_odp.02","label":"security functions (deployed in hardware)"},{"id":"ac-06.01_odp.03","label":"security functions (deployed in software)"},{"id":"ac-06.01_odp.04","label":"security functions (deployed in firmware)"},{"id":"ac-06.01_odp.05","label":"security-relevant information"}],"objectives":[{"id":"ac-6.1_obj.a-1","label":"AC-06(01)(a)[01]","text":"access is authorized for {{ insert: param, ac-06.01_odp.01 }} to {{ insert: param, ac-06.01_odp.02 }};"},{"id":"ac-6.1_obj.a-2","label":"AC-06(01)(a)[02]","text":"access is authorized for {{ insert: param, ac-06.01_odp.01 }} to {{ insert: param, ac-06.01_odp.03 }};"},{"id":"ac-6.1_obj.a-3","label":"AC-06(01)(a)[03]","text":"access is authorized for {{ insert: param, ac-06.01_odp.01 }} to {{ insert: param, ac-06.01_odp.04 }};"},{"id":"ac-6.1_obj.b","label":"AC-06(01)(b)","text":"access is authorized for {{ insert: param, ac-06.01_odp.01 }} to {{ insert: param, ac-06.01_odp.05 }}."}],"methods":[{"method":"examine","label":"AC-06(01)-Examine"},{"method":"interview","label":"AC-06(01)-Interview"},{"method":"test","label":"AC-06(01)-Test"}],"related_controls":["AC-17","AC-18","AC-19","AU-9","PE-2"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(2)","oscal_id":"ac-6.2","family":"AC","title":"Non-privileged Access for Nonsecurity Functions","statement":"Require that users of system accounts (or roles) with access to <security functions or security-relevant information> use non-privileged accounts or roles, when accessing nonsecurity functions.","supplemental_guidance":"Requiring the use of non-privileged accounts when accessing nonsecurity functions limits exposure when operating from within privileged accounts or roles. The inclusion of roles addresses situations where organizations implement access control policies, such as role-based access control, and where a change of role provides the same degree of assurance in the change of access authorizations for the user and the processes acting on behalf of the user as would be provided by a change between a privileged and non-privileged account.","implementation_level":"organization","parameters":[{"id":"ac-06.02_odp","label":"security functions or security-relevant information"}],"methods":[{"method":"examine","label":"AC-06(02)-Examine"},{"method":"interview","label":"AC-06(02)-Interview"},{"method":"test","label":"AC-06(02)-Test"}],"related_controls":["AC-17","AC-18","AC-19","PL-4"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(3)","oscal_id":"ac-6.3","family":"AC","title":"Network Access to Privileged Commands","statement":"Authorize network access to <privileged commands> only for <compelling operational needs> and document the rationale for such access in the security plan for the system.","supplemental_guidance":"Network access is any access across a network connection in lieu of local access (i.e., user being physically present at the device).","implementation_level":"organization","parameters":[{"id":"ac-06.03_odp.01","label":"privileged commands"},{"id":"ac-06.03_odp.02","label":"compelling operational needs"}],"objectives":[{"id":"ac-6.3_obj-1","label":"AC-06(03)[01]","text":"network access to {{ insert: param, ac-06.03_odp.01 }} is authorized only for {{ insert: param, ac-06.03_odp.02 }};"},{"id":"ac-6.3_obj-2","label":"AC-06(03)[02]","text":"the rationale for authorizing network access to privileged commands is documented in the security plan for the system."}],"methods":[{"method":"examine","label":"AC-06(03)-Examine"},{"method":"interview","label":"AC-06(03)-Interview"},{"method":"test","label":"AC-06(03)-Test"}],"related_controls":["AC-17","AC-18","AC-19"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(4)","oscal_id":"ac-6.4","family":"AC","title":"Separate Processing Domains","statement":"Provide separate processing domains to enable finer-grained allocation of user privileges.","supplemental_guidance":"Providing separate processing domains for finer-grained allocation of user privileges includes using virtualization techniques to permit additional user privileges within a virtual machine while restricting privileges to other virtual machines or to the underlying physical machine, implementing separate physical domains, and employing hardware or software domain separation mechanisms.","implementation_level":"organization","methods":[{"method":"examine","label":"AC-06(04)-Examine"},{"method":"interview","label":"AC-06(04)-Interview"},{"method":"test","label":"AC-06(04)-Test"}],"related_controls":["AC-4","SC-2","SC-3","SC-30","SC-32","SC-39"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(5)","oscal_id":"ac-6.5","family":"AC","title":"Privileged Accounts","statement":"Restrict privileged accounts on the system to <personnel or roles>.","supplemental_guidance":"Privileged accounts, including super user accounts, are typically described as system administrator for various types of commercial off-the-shelf operating systems. Restricting privileged accounts to specific personnel or roles prevents day-to-day users from accessing privileged information or privileged functions. Organizations may differentiate in the application of restricting privileged accounts between allowed privileges for local accounts and for domain accounts provided that they retain the ability to control system configurations for key parameters and as otherwise necessary to sufficiently mitigate risk.","implementation_level":"organization","parameters":[{"id":"ac-06.05_odp","label":"personnel or roles"}],"methods":[{"method":"examine","label":"AC-06(05)-Examine"},{"method":"interview","label":"AC-06(05)-Interview"},{"method":"test","label":"AC-06(05)-Test"}],"related_controls":["IA-2","MA-3","MA-4"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(6)","oscal_id":"ac-6.6","family":"AC","title":"Privileged Access by Non-organizational Users","statement":"Prohibit privileged access to the system by non-organizational users.","supplemental_guidance":"An organizational user is an employee or an individual considered by the organization to have the equivalent status of an employee. Organizational users include contractors, guest researchers, or individuals detailed from other organizations. A non-organizational user is a user who is not an organizational user. Policies and procedures for granting equivalent status of employees to individuals include a need-to-know, citizenship, and the relationship to the organization.","implementation_level":"organization","methods":[{"method":"examine","label":"AC-06(06)-Examine"},{"method":"interview","label":"AC-06(06)-Interview"},{"method":"test","label":"AC-06(06)-Test"}],"related_controls":["AC-18","AC-19","IA-2","IA-8"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(7)","oscal_id":"ac-6.7","family":"AC","title":"Review of User Privileges","statement":"(a) Review <frequency> the privileges assigned to <roles and classes> to validate the need for such privileges; and\n(b) Reassign or remove privileges, if necessary, to correctly reflect organizational mission and business needs.","supplemental_guidance":"The need for certain assigned user privileges may change over time to reflect changes in organizational mission and business functions, environments of operation, technologies, or threats. A periodic review of assigned user privileges is necessary to determine if the rationale for assigning such privileges remains valid. If the need cannot be revalidated, organizations take appropriate corrective actions.","implementation_level":"organization","parameters":[{"id":"ac-06.07_odp.01","label":"frequency"},{"id":"ac-06.07_odp.02","label":"roles and classes"}],"objectives":[{"id":"ac-6.7_obj.a","label":"AC-06(07)(a)","text":"privileges assigned to {{ insert: param, ac-06.07_odp.02 }} are reviewed {{ insert: param, ac-06.07_odp.01 }} to validate the need for such privileges;"},{"id":"ac-6.7_obj.b","label":"AC-06(07)(b)","text":"privileges are reassigned or removed, if necessary, to correctly reflect organizational mission and business needs."}],"methods":[{"method":"examine","label":"AC-06(07)-Examine"},{"method":"interview","label":"AC-06(07)-Interview"},{"method":"test","label":"AC-06(07)-Test"}],"related_controls":["CA-7"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(8)","oscal_id":"ac-6.8","family":"AC","title":"Privilege Levels for Code Execution","statement":"Prevent the following software from executing at higher privilege levels than users executing the software: <software>.","supplemental_guidance":"In certain situations, software applications or programs need to execute with elevated privileges to perform required functions. However, depending on the software functionality and configuration, if the privileges required for execution are at a higher level than the privileges assigned to organizational users invoking such applications or programs, those users may indirectly be provided with greater privileges than assigned.","implementation_level":"system","parameters":[{"id":"ac-06.08_odp","label":"software"}],"methods":[{"method":"examine","label":"AC-06(08)-Examine"},{"method":"interview","label":"AC-06(08)-Interview"},{"method":"test","label":"AC-06(08)-Test"}],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(9)","oscal_id":"ac-6.9","family":"AC","title":"Log Use of Privileged Functions","statement":"Log the execution of privileged functions.","supplemental_guidance":"The misuse of privileged functions, either intentionally or unintentionally by authorized users or by unauthorized external entities that have compromised system accounts, is a serious and ongoing concern and can have significant adverse impacts on organizations. Logging and analyzing the use of privileged functions is one way to detect such misuse and, in doing so, help mitigate the risk from insider threats and the advanced persistent threat.","implementation_level":"system","methods":[{"method":"examine","label":"AC-06(09)-Examine"},{"method":"interview","label":"AC-06(09)-Interview"},{"method":"test","label":"AC-06(09)-Test"}],"related_controls":["AU-2","AU-3","AU-12"],"is_enhancement":true,"parent_id":"AC-6"},{"id":"AC-6(10)","oscal_id":"ac-6.10","family":"AC","title":"Prohibit Non-privileged Users from Executing Privileged Functions","statement":"Prevent non-privileged users from executing privileged functions.","supplemental_guidance":"Privileged functions include disabling, circumventing, or altering implemented security or privacy controls, establishing system accounts, performing system integrity checks, and administering cryptographic key management activities. Non-privileged users are individuals who do not possess appropriate authorizations. Privileged functions that require protection from non-privileged users include circumventing intrusion detection and prevention mechanisms or malicious code protection mechanisms. Preventing non-privileged users from executing privileged functions is enforced by [AC-3](#ac-3).","implementation_level":"system","methods":[{"method":"examine","label":"AC-06(10)-Examine"},{"method":"interview","label":"AC-06(10)-Interview"},{"method":"test","label":"AC-06(10)-Test"}],"is_enhancement":true,"parent_id":"AC-6"}]},{"id":"AC-7","oscal_id":"ac-7","family":"AC","title":"Unsuccessful Logon Attempts","statement":"a. Enforce a limit of <number> consecutive invalid logon attempts by a user during a <time period> ; and\nb. Automatically <organization-defined parameter> when the maximum number of unsuccessful attempts is exceeded.","supplemental_guidance":"The need to limit unsuccessful logon attempts and take subsequent action when the maximum number of attempts is exceeded applies regardless of whether the logon occurs via a local or network connection. Due to the potential for denial of service, automatic lockouts initiated by systems are usually temporary and automatically release after a predetermined, organization-defined time period. If a delay algorithm is selected, organizations may employ different algorithms for different components of the system based on the capabilities of those components. Responses to unsuccessful logon attempts may be implemented at the operating system and the application levels. Organization-defined actions that may be taken when the number of allowed consecutive invalid logon attempts is exceeded include prompting the user to answer a secret question in addition to the username and password, invoking a lockdown mode with limited user capabilities (instead of full lockout), allowing users to only logon from specified Internet Protocol (IP) addresses, requiring a CAPTCHA to prevent automated attacks, or applying user profiles such as location, time of day, IP address, device, or Media Access Control (MAC) address. If automatic system lockout or execution of a delay algorithm is not implemented in support of the availability objective, organizations consider a combination of other actions to help prevent brute force attacks. In addition to the above, organizations can prompt users to respond to a secret question before the number of allowed unsuccessful logon attempts is exceeded. Automatically unlocking an account after a specified period of time is generally not permitted. However, exceptions may be required based on operational mission or need.","implementation_level":"system","parameters":[{"id":"ac-07_odp.01","label":"number"},{"id":"ac-07_odp.02","label":"time period"},{"id":"ac-07_odp.03","label":"","choices":["lock the account or node for {{ insert: param, ac-07_odp.04 }} ","lock the account or node until released by an administrator","delay next logon prompt per {{ insert: param, ac-07_odp.05 }} ","notify system administrator","take other {{ insert: param, ac-07_odp.06 }} "],"how_many":"one-or-more"},{"id":"ac-07_odp.04","label":"time period"},{"id":"ac-07_odp.05","label":"delay algorithm"},{"id":"ac-07_odp.06","label":"action"}],"objectives":[{"id":"ac-7_obj.a","label":"AC-07a.","text":"a limit of {{ insert: param, ac-07_odp.01 }} consecutive invalid logon attempts by a user during {{ insert: param, ac-07_odp.02 }} is enforced;"},{"id":"ac-7_obj.b","label":"AC-07b.","text":"automatically {{ insert: param, ac-07_odp.03 }} when the maximum number of unsuccessful attempts is exceeded."}],"methods":[{"method":"examine","label":"AC-07-Examine"},{"method":"interview","label":"AC-07-Interview"},{"method":"test","label":"AC-07-Test"}],"references":[{"title":"SP 800-63-3"},{"title":"SP 800-124"}],"related_controls":["AC-2","AC-9","AU-2","AU-6","IA-5"],"enhancements":[{"id":"AC-7(1)","oscal_id":"ac-7.1","family":"AC","title":"Automatic Account Lock","statement":"","is_enhancement":true,"parent_id":"AC-7"},{"id":"AC-7(2)","oscal_id":"ac-7.2","family":"AC","title":"Purge or Wipe Mobile Device","statement":"Purge or wipe information from <mobile devices> based on <purging or wiping requirements and techniques> after <number> consecutive, unsuccessful device logon attempts.","supplemental_guidance":"A mobile device is a computing device that has a small form factor such that it can be carried by a single individual; is designed to operate without a physical connection; possesses local, non-removable or removable data storage; and includes a self-contained power source. Purging or wiping the device applies only to mobile devices for which the organization-defined number of unsuccessful logons occurs. The logon is to the mobile device, not to any one account on the device. Successful logons to accounts on mobile devices reset the unsuccessful logon count to zero. Purging or wiping may be unnecessary if the information on the device is protected with sufficiently strong encryption mechanisms.","implementation_level":"system","parameters":[{"id":"ac-07.02_odp.01","label":"mobile devices"},{"id":"ac-07.02_odp.02","label":"purging or wiping requirements and techniques"},{"id":"ac-07.02_odp.03","label":"number"}],"methods":[{"method":"examine","label":"AC-07(02)-Examine"},{"method":"interview","label":"AC-07(02)-Interview"},{"method":"test","label":"AC-07(02)-Test"}],"related_controls":["AC-19","MP-5","MP-6"],"is_enhancement":true,"parent_id":"AC-7"},{"id":"AC-7(3)","oscal_id":"ac-7.3","family":"AC","title":"Biometric Attempt Limiting","statement":"Limit the number of unsuccessful biometric logon attempts to <number>.","supplemental_guidance":"Biometrics are probabilistic in nature. The ability to successfully authenticate can be impacted by many factors, including matching performance and presentation attack detection mechanisms. Organizations select the appropriate number of attempts for users based on organizationally-defined factors.","implementation_level":"organization","parameters":[{"id":"ac-07.03_odp","label":"number"}],"methods":[{"method":"examine","label":"AC-07(03)-Examine"},{"method":"interview","label":"AC-07(03)-Interview"},{"method":"test","label":"AC-07(03)-Test"}],"related_controls":["IA-3"],"is_enhancement":true,"parent_id":"AC-7"},{"id":"AC-7(4)","oscal_id":"ac-7.4","family":"AC","title":"Use of Alternate Authentication Factor","statement":"(a) Allow the use of <authentication factors> that are different from the primary authentication factors after the number of organization-defined consecutive invalid logon attempts have been exceeded; and\n(b) Enforce a limit of <number> consecutive invalid logon attempts through use of the alternative factors by a user during a <time period>.","supplemental_guidance":"The use of alternate authentication factors supports the objective of availability and allows a user who has inadvertently been locked out to use additional authentication factors to bypass the lockout.","implementation_level":"organization","parameters":[{"id":"ac-07.04_odp.01","label":"authentication factors"},{"id":"ac-07.04_odp.02","label":"number"},{"id":"ac-07.04_odp.03","label":"time period"}],"objectives":[{"id":"ac-7.4_obj.a","label":"AC-07(04)(a)","text":"{{ insert: param, ac-07.04_odp.01 }} that are different from the primary authentication factors are allowed to be used after the number of organization-defined consecutive invalid logon attempts have been exceeded;"},{"id":"ac-7.4_obj.b","label":"AC-07(04)(b)","text":"a limit of {{ insert: param, ac-07.04_odp.02 }} consecutive invalid logon attempts through the use of the alternative factors by the user during a {{ insert: param, ac-07.04_odp.03 }} is enforced."}],"methods":[{"method":"examine","label":"AC-07(04)-Examine"},{"method":"interview","label":"AC-07(04)-Interview"},{"method":"test","label":"AC-07(04)-Test"}],"related_controls":["IA-3"],"is_enhancement":true,"parent_id":"AC-7"}]},{"id":"AC-8","oscal_id":"ac-8","family":"AC","title":"System Use Notification","statement":"a. Display <system use notification> to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that:\n  Display <system use notification> to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that:\n  1. Users are accessing a U.S. Government system;\n  2. System usage may be monitored, recorded, and subject to audit;\n  3. Unauthorized use of the system is prohibited and subject to criminal and civil penalties; and\n  4. Use of the system indicates consent to monitoring and recording;\nb. Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system; and\nc. For publicly accessible systems:\n  For publicly accessible systems:\n  1. Display system use information <conditions> , before granting further access to the publicly accessible system;\n  2. Display references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and\n  3. Include a description of the authorized uses of the system.","supplemental_guidance":"System use notifications can be implemented using messages or warning banners displayed before individuals log in to systems. System use notifications are used only for access via logon interfaces with human users. Notifications are not required when human interfaces do not exist. Based on an assessment of risk, organizations consider whether or not a secondary system use notification is needed to access applications or other system resources after the initial network logon. Organizations consider system use notification messages or banners displayed in multiple languages based on organizational needs and the demographics of system users. Organizations consult with the privacy office for input regarding privacy messaging and the Office of the General Counsel or organizational equivalent for legal review and approval of warning banner content.","implementation_level":"organization","parameters":[{"id":"ac-08_odp.01","label":"system use notification"},{"id":"ac-08_odp.02","label":"conditions"}],"objectives":[{"id":"ac-8_obj.a","label":"AC-08a.","text":"{{ insert: param, ac-08_odp.01 }} is displayed to users before granting access to the system that provides privacy and security notices consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"ac-8_obj.a.1","label":"AC-08a.01","text":"the system use notification states that users are accessing a U.S. Government system;"},{"id":"ac-8_obj.a.2","label":"AC-08a.02","text":"the system use notification states that system usage may be monitored, recorded, and subject to audit;"},{"id":"ac-8_obj.a.3","label":"AC-08a.03","text":"the system use notification states that unauthorized use of the system is prohibited and subject to criminal and civil penalties; and"},{"id":"ac-8_obj.a.4","label":"AC-08a.04","text":"the system use notification states that use of the system indicates consent to monitoring and recording;"},{"id":"ac-8_obj.b","label":"AC-08b.","text":"the notification message or banner is retained on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system;"},{"id":"ac-8_obj.c.1","label":"AC-08c.01","text":"for publicly accessible systems, system use information {{ insert: param, ac-08_odp.02 }} is displayed before granting further access to the publicly accessible system;"},{"id":"ac-8_obj.c.2","label":"AC-08c.02","text":"for publicly accessible systems, any references to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities are displayed;"},{"id":"ac-8_obj.c.3","label":"AC-08c.03","text":"for publicly accessible systems, a description of the authorized uses of the system is included."}],"methods":[{"method":"examine","label":"AC-08-Examine"},{"method":"interview","label":"AC-08-Interview"},{"method":"test","label":"AC-08-Test"}],"related_controls":["AC-14","PL-4","SI-4"]},{"id":"AC-9","oscal_id":"ac-9","family":"AC","title":"Previous Logon Notification","statement":"Notify the user, upon successful logon to the system, of the date and time of the last logon.","supplemental_guidance":"Previous logon notification is applicable to system access via human user interfaces and access to systems that occurs in other types of architectures. Information about the last successful logon allows the user to recognize if the date and time provided is not consistent with the user’s last access.","implementation_level":"system","methods":[{"method":"examine","label":"AC-09-Examine"},{"method":"interview","label":"AC-09-Interview"},{"method":"test","label":"AC-09-Test"}],"related_controls":["AC-7","PL-4"],"enhancements":[{"id":"AC-9(1)","oscal_id":"ac-9.1","family":"AC","title":"Unsuccessful Logons","statement":"Notify the user, upon successful logon, of the number of unsuccessful logon attempts since the last successful logon.","supplemental_guidance":"Information about the number of unsuccessful logon attempts since the last successful logon allows the user to recognize if the number of unsuccessful logon attempts is consistent with the user’s actual logon attempts.","implementation_level":"system","methods":[{"method":"examine","label":"AC-09(01)-Examine"},{"method":"interview","label":"AC-09(01)-Interview"},{"method":"test","label":"AC-09(01)-Test"}],"is_enhancement":true,"parent_id":"AC-9"},{"id":"AC-9(2)","oscal_id":"ac-9.2","family":"AC","title":"Successful and Unsuccessful Logons","statement":"Notify the user, upon successful logon, of the number of <organization-defined parameter> during <time period>.","supplemental_guidance":"Information about the number of successful and unsuccessful logon attempts within a specified time period allows the user to recognize if the number and type of logon attempts are consistent with the user’s actual logon attempts.","implementation_level":"system","parameters":[{"id":"ac-09.02_odp.01","label":"","choices":["successful logons","unsuccessful logon attempts","both"]},{"id":"ac-09.02_odp.02","label":"time period"}],"methods":[{"method":"examine","label":"AC-09(02)-Examine"},{"method":"interview","label":"AC-09(02)-Interview"},{"method":"test","label":"AC-09(02)-Test"}],"is_enhancement":true,"parent_id":"AC-9"},{"id":"AC-9(3)","oscal_id":"ac-9.3","family":"AC","title":"Notification of Account Changes","statement":"Notify the user, upon successful logon, of changes to <security-related characteristics or parameters> during <time period>.","supplemental_guidance":"Information about changes to security-related account characteristics within a specified time period allows users to recognize if changes were made without their knowledge.","implementation_level":"system","parameters":[{"id":"ac-09.03_odp.01","label":"security-related characteristics or parameters"},{"id":"ac-09.03_odp.02","label":"time period"}],"methods":[{"method":"examine","label":"AC-09(03)-Examine"},{"method":"interview","label":"AC-09(03)-Interview"},{"method":"test","label":"AC-09(03)-Test"}],"is_enhancement":true,"parent_id":"AC-9"},{"id":"AC-9(4)","oscal_id":"ac-9.4","family":"AC","title":"Additional Logon Information","statement":"Notify the user, upon successful logon, of the following additional information: <additional information>.","supplemental_guidance":"Organizations can specify additional information to be provided to users upon logon, including the location of the last logon. User location is defined as information that can be determined by systems, such as Internet Protocol (IP) addresses from which network logons occurred, notifications of local logons, or device identifiers.","implementation_level":"system","parameters":[{"id":"ac-09.04_odp","label":"additional information"}],"methods":[{"method":"examine","label":"AC-09(04)-Examine"},{"method":"interview","label":"AC-09(04)-Interview"},{"method":"test","label":"AC-09(04)-Test"}],"is_enhancement":true,"parent_id":"AC-9"}]},{"id":"AC-10","oscal_id":"ac-10","family":"AC","title":"Concurrent Session Control","statement":"Limit the number of concurrent sessions for each <account and/or account types> to <number>.","supplemental_guidance":"Organizations may define the maximum number of concurrent sessions for system accounts globally, by account type, by account, or any combination thereof. For example, organizations may limit the number of concurrent sessions for system administrators or other individuals working in particularly sensitive domains or mission-critical applications. Concurrent session control addresses concurrent sessions for system accounts. It does not, however, address concurrent sessions by single users via multiple system accounts.","implementation_level":"system","parameters":[{"id":"ac-10_odp.01","label":"account and/or account types"},{"id":"ac-10_odp.02","label":"number"}],"methods":[{"method":"examine","label":"AC-10-Examine"},{"method":"interview","label":"AC-10-Interview"},{"method":"test","label":"AC-10-Test"}],"related_controls":["SC-23"]},{"id":"AC-11","oscal_id":"ac-11","family":"AC","title":"Device Lock","statement":"a. Prevent further access to the system by <organization-defined parameter> ; and\nb. Retain the device lock until the user reestablishes access using established identification and authentication procedures.","supplemental_guidance":"Device locks are temporary actions taken to prevent logical access to organizational systems when users stop work and move away from the immediate vicinity of those systems but do not want to log out because of the temporary nature of their absences. Device locks can be implemented at the operating system level or at the application level. A proximity lock may be used to initiate the device lock (e.g., via a Bluetooth-enabled device or dongle). User-initiated device locking is behavior or policy-based and, as such, requires users to take physical action to initiate the device lock. Device locks are not an acceptable substitute for logging out of systems, such as when organizations require users to log out at the end of workdays.","implementation_level":"system","parameters":[{"id":"ac-11_odp.01","label":"","choices":["initiating a device lock after {{ insert: param, ac-11_odp.02 }} of inactivity","requiring the user to initiate a device lock before leaving the system unattended"],"how_many":"one-or-more"},{"id":"ac-11_odp.02","label":"time period"}],"objectives":[{"id":"ac-11_obj.a","label":"AC-11a.","text":"further access to the system is prevented by {{ insert: param, ac-11_odp.01 }};"},{"id":"ac-11_obj.b","label":"AC-11b.","text":"device lock is retained until the user re-establishes access using established identification and authentication procedures."}],"methods":[{"method":"examine","label":"AC-11-Examine"},{"method":"interview","label":"AC-11-Interview"},{"method":"test","label":"AC-11-Test"}],"related_controls":["AC-2","AC-7","IA-11","PL-4"],"enhancements":[{"id":"AC-11(1)","oscal_id":"ac-11.1","family":"AC","title":"Pattern-hiding Displays","statement":"Conceal, via the device lock, information previously visible on the display with a publicly viewable image.","supplemental_guidance":"The pattern-hiding display can include static or dynamic images, such as patterns used with screen savers, photographic images, solid colors, clock, battery life indicator, or a blank screen with the caveat that controlled unclassified information is not displayed.","implementation_level":"system","methods":[{"method":"examine","label":"AC-11(01)-Examine"},{"method":"interview","label":"AC-11(01)-Interview"},{"method":"test","label":"AC-11(01)-Test"}],"is_enhancement":true,"parent_id":"AC-11"}]},{"id":"AC-12","oscal_id":"ac-12","family":"AC","title":"Session Termination","statement":"Automatically terminate a user session after <conditions or trigger events>.","supplemental_guidance":"Session termination addresses the termination of user-initiated logical sessions (in contrast to [SC-10](#sc-10) , which addresses the termination of network connections associated with communications sessions (i.e., network disconnect)). A logical session (for local, network, and remote access) is initiated whenever a user (or process acting on behalf of a user) accesses an organizational system. Such user sessions can be terminated without terminating network sessions. Session termination ends all processes associated with a user’s logical session except for those processes that are specifically created by the user (i.e., session owner) to continue after the session is terminated. Conditions or trigger events that require automatic termination of the session include organization-defined periods of user inactivity, targeted responses to certain types of incidents, or time-of-day restrictions on system use.","implementation_level":"system","parameters":[{"id":"ac-12_odp","label":"conditions or trigger events"}],"methods":[{"method":"examine","label":"AC-12-Examine"},{"method":"interview","label":"AC-12-Interview"},{"method":"test","label":"AC-12-Test"}],"related_controls":["MA-4","SC-10","SC-23"],"enhancements":[{"id":"AC-12(1)","oscal_id":"ac-12.1","family":"AC","title":"User-initiated Logouts","statement":"Provide a logout capability for user-initiated communications sessions whenever authentication is used to gain access to <information resources>.","supplemental_guidance":"Information resources to which users gain access via authentication include local workstations, databases, and password-protected websites or web-based services.","implementation_level":"organization","parameters":[{"id":"ac-12.01_odp","label":"information resources"}],"methods":[{"method":"examine","label":"AC-12(01)-Examine"},{"method":"interview","label":"AC-12(01)-Interview"},{"method":"test","label":"AC-12(01)-Test"}],"is_enhancement":true,"parent_id":"AC-12"},{"id":"AC-12(2)","oscal_id":"ac-12.2","family":"AC","title":"Termination Message","statement":"Display an explicit logout message to users indicating the termination of authenticated communications sessions.","supplemental_guidance":"Logout messages for web access can be displayed after authenticated sessions have been terminated. However, for certain types of sessions, including file transfer protocol (FTP) sessions, systems typically send logout messages as final messages prior to terminating sessions.","implementation_level":"system","methods":[{"method":"examine","label":"AC-12(02)-Examine"},{"method":"interview","label":"AC-12(02)-Interview"},{"method":"test","label":"AC-12(02)-Test"}],"is_enhancement":true,"parent_id":"AC-12"},{"id":"AC-12(3)","oscal_id":"ac-12.3","family":"AC","title":"Timeout Warning Message","statement":"Display an explicit message to users indicating that the session will end in <time>.","supplemental_guidance":"To increase usability, notify users of pending session termination and prompt users to continue the session. The pending session termination time period is based on the parameters defined in the [AC-12](#ac-12) base control.","implementation_level":"system","parameters":[{"id":"ac-12.03_odp","label":"time"}],"methods":[{"method":"examine","label":"AC-12(03)-Examine"},{"method":"interview","label":"AC-12(03)-Interview"},{"method":"test","label":"AC-12(03)-Test"}],"is_enhancement":true,"parent_id":"AC-12"}]},{"id":"AC-13","oscal_id":"ac-13","family":"AC","title":"Supervision and Review — Access Control","statement":""},{"id":"AC-14","oscal_id":"ac-14","family":"AC","title":"Permitted Actions Without Identification or Authentication","statement":"a. Identify <user actions> that can be performed on the system without identification or authentication consistent with organizational mission and business functions; and\nb. Document and provide supporting rationale in the security plan for the system, user actions not requiring identification or authentication.","supplemental_guidance":"Specific user actions may be permitted without identification or authentication if organizations determine that identification and authentication are not required for the specified user actions. Organizations may allow a limited number of user actions without identification or authentication, including when individuals access public websites or other publicly accessible federal systems, when individuals use mobile phones to receive calls, or when facsimiles are received. Organizations identify actions that normally require identification or authentication but may, under certain circumstances, allow identification or authentication mechanisms to be bypassed. Such bypasses may occur, for example, via a software-readable physical switch that commands bypass of the logon functionality and is protected from accidental or unmonitored use. Permitting actions without identification or authentication does not apply to situations where identification and authentication have already occurred and are not repeated but rather to situations where identification and authentication have not yet occurred. Organizations may decide that there are no user actions that can be performed on organizational systems without identification and authentication, and therefore, the value for the assignment operation can be \"none.\"","implementation_level":"organization","parameters":[{"id":"ac-14_odp","label":"user actions"}],"objectives":[{"id":"ac-14_obj.a","label":"AC-14a.","text":"{{ insert: param, ac-14_odp }} that can be performed on the system without identification or authentication consistent with organizational mission and business functions are identified;"},{"id":"ac-14_obj.b-1","label":"AC-14b.[01]","text":"user actions not requiring identification or authentication are documented in the security plan for the system;"},{"id":"ac-14_obj.b-2","label":"AC-14b.[02]","text":"a rationale for user actions not requiring identification or authentication is provided in the security plan for the system."}],"methods":[{"method":"examine","label":"AC-14-Examine"},{"method":"interview","label":"AC-14-Interview"}],"related_controls":["AC-8","IA-2","PL-2"],"enhancements":[{"id":"AC-14(1)","oscal_id":"ac-14.1","family":"AC","title":"Necessary Uses","statement":"","is_enhancement":true,"parent_id":"AC-14"}]},{"id":"AC-15","oscal_id":"ac-15","family":"AC","title":"Automated Marking","statement":""},{"id":"AC-16","oscal_id":"ac-16","family":"AC","title":"Security and Privacy Attributes","statement":"a. Provide the means to associate <organization-defined types of security and privacy attributes> with <organization-defined security and privacy attribute values> for information in storage, in process, and/or in transmission;\nb. Ensure that the attribute associations are made and retained with the information;\nc. Establish the following permitted security and privacy attributes from the attributes defined in [AC-16a](#ac-16_smt.a) for <organization-defined systems>: <organization-defined security and privacy attributes>;\nd. Determine the following permitted attribute values or ranges for each of the established attributes: <attribute values or ranges>;\ne. Audit changes to attributes; and\nf. Review <organization-defined security and privacy attributes> for applicability <organization-defined frequency>.","supplemental_guidance":"Information is represented internally within systems using abstractions known as data structures. Internal data structures can represent different types of entities, both active and passive. Active entities, also known as subjects, are typically associated with individuals, devices, or processes acting on behalf of individuals. Passive entities, also known as objects, are typically associated with data structures, such as records, buffers, tables, files, inter-process pipes, and communications ports. Security attributes, a form of metadata, are abstractions that represent the basic properties or characteristics of active and passive entities with respect to safeguarding information. Privacy attributes, which may be used independently or in conjunction with security attributes, represent the basic properties or characteristics of active or passive entities with respect to the management of personally identifiable information. Attributes can be either explicitly or implicitly associated with the information contained in organizational systems or system components.\n\nAttributes may be associated with active entities (i.e., subjects) that have the potential to send or receive information, cause information to flow among objects, or change the system state. These attributes may also be associated with passive entities (i.e., objects) that contain or receive information. The association of attributes to subjects and objects by a system is referred to as binding and is inclusive of setting the attribute value and the attribute type. Attributes, when bound to data or information, permit the enforcement of security and privacy policies for access control and information flow control, including data retention limits, permitted uses of personally identifiable information, and identification of personal information within data objects. Such enforcement occurs through organizational processes or system functions or mechanisms. The binding techniques implemented by systems affect the strength of attribute binding to information. Binding strength and the assurance associated with binding techniques play important parts in the trust that organizations have in the information flow enforcement process. The binding techniques affect the number and degree of additional reviews required by organizations. The content or assigned values of attributes can directly affect the ability of individuals to access organizational information.\n\nOrganizations can define the types of attributes needed for systems to support missions or business functions. There are many values that can be assigned to a security attribute. By specifying the permitted attribute ranges and values, organizations ensure that attribute values are meaningful and relevant. Labeling refers to the association of attributes with the subjects and objects represented by the internal data structures within systems. This facilitates system-based enforcement of information security and privacy policies. Labels include classification of information in accordance with legal and compliance requirements (e.g., top secret, secret, confidential, controlled unclassified), information impact level; high value asset information, access authorizations, nationality; data life cycle protection (i.e., encryption and data expiration), personally identifiable information processing permissions, including individual consent to personally identifiable information processing, and contractor affiliation. A related term to labeling is marking. Marking refers to the association of attributes with objects in a human-readable form and displayed on system media. Marking enables manual, procedural, or process-based enforcement of information security and privacy policies. Security and privacy labels may have the same value as media markings (e.g., top secret, secret, confidential). See [MP-3](#mp-3) (Media Marking).","implementation_level":"organization","parameters":[{"id":"ac-16_prm_1","label":"organization-defined types of security and privacy attributes"},{"id":"ac-16_prm_2","label":"organization-defined security and privacy attribute values"},{"id":"ac-16_prm_3","label":"organization-defined systems"},{"id":"ac-16_prm_4","label":"organization-defined security and privacy attributes"},{"id":"ac-16_prm_6","label":"organization-defined security and privacy attributes"},{"id":"ac-16_prm_7","label":"organization-defined frequency"},{"id":"ac-16_odp.01","label":"types of security attributes"},{"id":"ac-16_odp.02","label":"types of privacy attributes"},{"id":"ac-16_odp.03","label":"security attribute values"},{"id":"ac-16_odp.04","label":"privacy attribute values"},{"id":"ac-16_odp.05","label":"systems"},{"id":"ac-16_odp.06","label":"systems"},{"id":"ac-16_odp.07","label":"security attributes"},{"id":"ac-16_odp.08","label":"privacy attributes"},{"id":"ac-16_odp.09","label":"attribute values or ranges"},{"id":"ac-16_odp.10","label":"frequency"},{"id":"ac-16_odp.11","label":"frequency"}],"objectives":[{"id":"ac-16_obj.a-1","label":"AC-16a.[01]","text":"the means to associate {{ insert: param, ac-16_odp.01 }} with {{ insert: param, ac-16_odp.03 }} for information in storage, in process, and/or in transmission are provided;"},{"id":"ac-16_obj.a-2","label":"AC-16a.[02]","text":"the means to associate {{ insert: param, ac-16_odp.02 }} with {{ insert: param, ac-16_odp.04 }} for information in storage, in process, and/or in transmission are provided;"},{"id":"ac-16_obj.b-1","label":"AC-16b.[01]","text":"attribute associations are made;"},{"id":"ac-16_obj.b-2","label":"AC-16b.[02]","text":"attribute associations are retained with the information;"},{"id":"ac-16_obj.c-1","label":"AC-16c.[01]","text":"the following permitted security attributes are established from the attributes defined in AC-16_ODP[01] for {{ insert: param, ac-16_odp.05 }}: {{ insert: param, ac-16_odp.07 }};"},{"id":"ac-16_obj.c-2","label":"AC-16c.[02]","text":"the following permitted privacy attributes are established from the attributes defined in AC-16_ODP[02] for {{ insert: param, ac-16_odp.06 }}: {{ insert: param, ac-16_odp.08 }};"},{"id":"ac-16_obj.d","label":"AC-16d.","text":"the following permitted attribute values or ranges for each of the established attributes are determined: {{ insert: param, ac-16_odp.09 }};"},{"id":"ac-16_obj.e","label":"AC-16e.","text":"changes to attributes are audited;"},{"id":"ac-16_obj.f-1","label":"AC-16f.[01]","text":"{{ insert: param, ac-16_odp.07 }} are reviewed for applicability {{ insert: param, ac-16_odp.10 }};"},{"id":"ac-16_obj.f-2","label":"AC-16f.[02]","text":"{{ insert: param, ac-16_odp.08 }} are reviewed for applicability {{ insert: param, ac-16_odp.11 }}."}],"methods":[{"method":"examine","label":"AC-16-Examine"},{"method":"interview","label":"AC-16-Interview"},{"method":"test","label":"AC-16-Test"}],"references":[{"title":"OMB A-130"},{"title":"FIPS 140-3"},{"title":"FIPS 186-4"},{"title":"SP 800-162"},{"title":"SP 800-178"}],"related_controls":["AC-3","AC-4","AC-6","AC-21","AC-25","AU-2","AU-10","MP-3","PE-22","PT-2","PT-3","PT-4","SC-11","SC-16","SI-12","SI-18"],"enhancements":[{"id":"AC-16(1)","oscal_id":"ac-16.1","family":"AC","title":"Dynamic Attribute Association","statement":"Dynamically associate security and privacy attributes with <organization-defined subjects and objects> in accordance with the following security and privacy policies as information is created and combined: <organization-defined security and privacy policies>.","supplemental_guidance":"Dynamic association of attributes is appropriate whenever the security or privacy characteristics of information change over time. Attributes may change due to information aggregation issues (i.e., characteristics of individual data elements are different from the combined elements), changes in individual access authorizations (i.e., privileges), changes in the security category of information, or changes in security or privacy policies. Attributes may also change situationally.","implementation_level":"system","parameters":[{"id":"ac-16.1_prm_1","label":"organization-defined subjects and objects"},{"id":"ac-16.1_prm_2","label":"organization-defined security and privacy policies"},{"id":"ac-16.01_odp.01","label":"subjects"},{"id":"ac-16.01_odp.02","label":"objects"},{"id":"ac-16.01_odp.03","label":"subjects"},{"id":"ac-16.01_odp.04","label":"objects"},{"id":"ac-16.01_odp.05","label":"security policies"},{"id":"ac-16.01_odp.06","label":"privacy policies"}],"objectives":[{"id":"ac-16.1_obj-1","label":"AC-16(01)[01]","text":"security attributes are dynamically associated with {{ insert: param, ac-16.01_odp.01 }} in accordance with the following security policies as information is created and combined: {{ insert: param, ac-16.01_odp.05 }};"},{"id":"ac-16.1_obj-2","label":"AC-16(01)[02]","text":"security attributes are dynamically associated with {{ insert: param, ac-16.01_odp.02 }} in accordance with the following security policies as information is created and combined: {{ insert: param, ac-16.01_odp.05 }};"},{"id":"ac-16.1_obj-3","label":"AC-16(01)[03]","text":"privacy attributes are dynamically associated with {{ insert: param, ac-16.01_odp.03 }} in accordance with the following privacy policies as information is created and combined: {{ insert: param, ac-16.01_odp.06 }};"},{"id":"ac-16.1_obj-4","label":"AC-16(01)[04]","text":"privacy attributes are dynamically associated with {{ insert: param, ac-16.01_odp.04 }} in accordance with the following privacy policies as information is created and combined: {{ insert: param, ac-16.01_odp.06 }}."}],"methods":[{"method":"examine","label":"AC-16(01)-Examine"},{"method":"interview","label":"AC-16(01)-Interview"},{"method":"test","label":"AC-16(01)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(2)","oscal_id":"ac-16.2","family":"AC","title":"Attribute Value Changes by Authorized Individuals","statement":"Provide authorized individuals (or processes acting on behalf of individuals) the capability to define or change the value of associated security and privacy attributes.","supplemental_guidance":"The content or assigned values of attributes can directly affect the ability of individuals to access organizational information. Therefore, it is important for systems to be able to limit the ability to create or modify attributes to authorized individuals.","implementation_level":"system","objectives":[{"id":"ac-16.2_obj-1","label":"AC-16(02)[01]","text":"authorized individuals (or processes acting on behalf of individuals) are provided with the capability to define or change the value of associated security attributes;"},{"id":"ac-16.2_obj-2","label":"AC-16(02)[02]","text":"authorized individuals (or processes acting on behalf of individuals) are provided with the capability to define or change the value of associated privacy attributes."}],"methods":[{"method":"examine","label":"AC-16(02)-Examine"},{"method":"interview","label":"AC-16(02)-Interview"},{"method":"test","label":"AC-16(02)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(3)","oscal_id":"ac-16.3","family":"AC","title":"Maintenance of Attribute Associations by System","statement":"Maintain the association and integrity of <organization-defined security and privacy attributes> to <organization-defined subjects and objects>.","supplemental_guidance":"Maintaining the association and integrity of security and privacy attributes to subjects and objects with sufficient assurance helps to ensure that the attribute associations can be used as the basis of automated policy actions. The integrity of specific items, such as security configuration files, may be maintained through the use of an integrity monitoring mechanism that detects anomalies and changes that deviate from \"known good\" baselines. Automated policy actions include retention date expirations, access control decisions, information flow control decisions, and information disclosure decisions.","implementation_level":"system","parameters":[{"id":"ac-16.3_prm_1","label":"organization-defined security and privacy attributes"},{"id":"ac-16.3_prm_2","label":"organization-defined subjects and objects"},{"id":"ac-16.03_odp.01","label":"security attributes"},{"id":"ac-16.03_odp.02","label":"privacy attributes"},{"id":"ac-16.03_odp.03","label":"subjects"},{"id":"ac-16.03_odp.04","label":"objects"},{"id":"ac-16.03_odp.05","label":"subjects"},{"id":"ac-16.03_odp.06","label":"objects"}],"objectives":[{"id":"ac-16.3_obj-1","label":"AC-16(03)[01]","text":"the association and integrity of {{ insert: param, ac-16.03_odp.01 }} to {{ insert: param, ac-16.03_odp.03 }} is maintained;"},{"id":"ac-16.3_obj-2","label":"AC-16(03)[02]","text":"the association and integrity of {{ insert: param, ac-16.03_odp.01 }} to {{ insert: param, ac-16.03_odp.04 }} is maintained."},{"id":"ac-16.3_obj-3","label":"AC-16(03)[03]","text":"the association and integrity of {{ insert: param, ac-16.03_odp.02 }} to {{ insert: param, ac-16.03_odp.05 }} is maintained;"},{"id":"ac-16.3_obj-4","label":"AC-16(03)[04]","text":"the association and integrity of {{ insert: param, ac-16.03_odp.02 }} to {{ insert: param, ac-16.03_odp.06 }} is maintained."}],"methods":[{"method":"examine","label":"AC-16(03)-Examine"},{"method":"interview","label":"AC-16(03)-Interview"},{"method":"test","label":"AC-16(03)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(4)","oscal_id":"ac-16.4","family":"AC","title":"Association of Attributes by Authorized Individuals","statement":"Provide the capability to associate <organization-defined security and privacy attributes> with <organization-defined subjects and objects> by authorized individuals (or processes acting on behalf of individuals).","supplemental_guidance":"Systems, in general, provide the capability for privileged users to assign security and privacy attributes to system-defined subjects (e.g., users) and objects (e.g., directories, files, and ports). Some systems provide additional capability for general users to assign security and privacy attributes to additional objects (e.g., files, emails). The association of attributes by authorized individuals is described in the design documentation. The support provided by systems can include prompting users to select security and privacy attributes to be associated with information objects, employing automated mechanisms to categorize information with attributes based on defined policies, or ensuring that the combination of the security or privacy attributes selected is valid. Organizations consider the creation, deletion, or modification of attributes when defining auditable events.","implementation_level":"system","parameters":[{"id":"ac-16.4_prm_1","label":"organization-defined security and privacy attributes"},{"id":"ac-16.4_prm_2","label":"organization-defined subjects and objects"},{"id":"ac-16.04_odp.01","label":"security attributes"},{"id":"ac-16.04_odp.02","label":"security attributes"},{"id":"ac-16.04_odp.03","label":"privacy attributes"},{"id":"ac-16.04_odp.04","label":"privacy attributes"},{"id":"ac-16.04_odp.05","label":"subjects"},{"id":"ac-16.04_odp.06","label":"objects"},{"id":"ac-16.04_odp.07","label":"subjects"},{"id":"ac-16.04_odp.08","label":"objects"}],"objectives":[{"id":"ac-16.4_obj-1","label":"AC-16(04)[01]","text":"authorized individuals (or processes acting on behalf of individuals) are provided with the capability to associate {{ insert: param, ac-16.04_odp.01 }} with {{ insert: param, ac-16.04_odp.05 }};"},{"id":"ac-16.4_obj-2","label":"AC-16(04)[02]","text":"authorized individuals (or processes acting on behalf of individuals) are provided with the capability to associate {{ insert: param, ac-16.04_odp.02 }} with {{ insert: param, ac-16.04_odp.06 }};"},{"id":"ac-16.4_obj-3","label":"AC-16(04)[03]","text":"authorized individuals (or processes acting on behalf of individuals) are provided with the capability to associate {{ insert: param, ac-16.04_odp.03 }} with {{ insert: param, ac-16.04_odp.07 }};"},{"id":"ac-16.4_obj-4","label":"AC-16(04)[04]","text":"authorized individuals (or processes acting on behalf of individuals) are provided with the capability to associate {{ insert: param, ac-16.04_odp.04 }} with {{ insert: param, ac-16.04_odp.08 }}."}],"methods":[{"method":"examine","label":"AC-16(04)-Examine"},{"method":"interview","label":"AC-16(04)-Interview"},{"method":"test","label":"AC-16(04)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(5)","oscal_id":"ac-16.5","family":"AC","title":"Attribute Displays on Objects to Be Output","statement":"Display security and privacy attributes in human-readable form on each object that the system transmits to output devices to identify <instructions> using <naming conventions>.","supplemental_guidance":"System outputs include printed pages, screens, or equivalent items. System output devices include printers, notebook computers, video displays, smart phones, and tablets. To mitigate the risk of unauthorized exposure of information (e.g., shoulder surfing), the outputs display full attribute values when unmasked by the subscriber.","implementation_level":"system","parameters":[{"id":"ac-16.05_odp.01","label":"instructions"},{"id":"ac-16.05_odp.02","label":"naming conventions"}],"objectives":[{"id":"ac-16.5_obj-1","label":"AC-16(05)[01]","text":"security attributes are displayed in human-readable form on each object that the system transmits to output devices to identify {{ insert: param, ac-16.05_odp.01 }} using {{ insert: param, ac-16.05_odp.02 }};"},{"id":"ac-16.5_obj-2","label":"AC-16(05)[02]","text":"privacy attributes are displayed in human-readable form on each object that the system transmits to output devices to identify {{ insert: param, ac-16.05_odp.01 }} using {{ insert: param, ac-16.05_odp.02 }}."}],"methods":[{"method":"examine","label":"AC-16(05)-Examine"},{"method":"interview","label":"AC-16(05)-Interview"},{"method":"test","label":"AC-16(05)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(6)","oscal_id":"ac-16.6","family":"AC","title":"Maintenance of Attribute Association","statement":"Require personnel to associate and maintain the association of <organization-defined security and privacy attributes> with <organization-defined subjects and objects> in accordance with <organization-defined security and privacy policies>.","supplemental_guidance":"Maintaining attribute association requires individual users (as opposed to the system) to maintain associations of defined security and privacy attributes with subjects and objects.","implementation_level":"organization","parameters":[{"id":"ac-16.6_prm_1","label":"organization-defined security and privacy attributes"},{"id":"ac-16.6_prm_2","label":"organization-defined subjects and objects"},{"id":"ac-16.6_prm_3","label":"organization-defined security and privacy policies"},{"id":"ac-16.06_odp.01","label":"security attributes"},{"id":"ac-16.06_odp.02","label":"security attributes"},{"id":"ac-16.06_odp.03","label":"privacy attributes"},{"id":"ac-16.06_odp.04","label":"privacy attributes"},{"id":"ac-16.06_odp.05","label":"subjects"},{"id":"ac-16.06_odp.06","label":"objects"},{"id":"ac-16.06_odp.07","label":"subjects"},{"id":"ac-16.06_odp.08","label":"objects"},{"id":"ac-16.06_odp.09","label":"security policies"},{"id":"ac-16.06_odp.10","label":"privacy policies"}],"objectives":[{"id":"ac-16.6_obj-1","label":"AC-16(06)[01]","text":"personnel are required to associate and maintain the association of {{ insert: param, ac-16.06_odp.01 }} with {{ insert: param, ac-16.06_odp.05 }} in accordance with {{ insert: param, ac-16.06_odp.09 }};"},{"id":"ac-16.6_obj-2","label":"AC-16(06)[02]","text":"personnel are required to associate and maintain the association of {{ insert: param, ac-16.06_odp.02 }} with {{ insert: param, ac-16.06_odp.06 }} in accordance with {{ insert: param, ac-16.06_odp.09 }};"},{"id":"ac-16.6_obj-3","label":"AC-16(06)[03]","text":"personnel are required to associate and maintain the association of {{ insert: param, ac-16.06_odp.03 }} with {{ insert: param, ac-16.06_odp.07 }} in accordance with {{ insert: param, ac-16.06_odp.10 }};"},{"id":"ac-16.6_obj-4","label":"AC-16(06)[04]","text":"personnel are required to associate and maintain the association of {{ insert: param, ac-16.06_odp.04 }} with {{ insert: param, ac-16.06_odp.08 }} in accordance with {{ insert: param, ac-16.06_odp.10 }}."}],"methods":[{"method":"examine","label":"AC-16(06)-Examine"},{"method":"interview","label":"AC-16(06)-Interview"},{"method":"test","label":"AC-16(06)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(7)","oscal_id":"ac-16.7","family":"AC","title":"Consistent Attribute Interpretation","statement":"Provide a consistent interpretation of security and privacy attributes transmitted between distributed system components.","supplemental_guidance":"To enforce security and privacy policies across multiple system components in distributed systems, organizations provide a consistent interpretation of security and privacy attributes employed in access enforcement and flow enforcement decisions. Organizations can establish agreements and processes to help ensure that distributed system components implement attributes with consistent interpretations in automated access enforcement and flow enforcement actions.","implementation_level":"organization","objectives":[{"id":"ac-16.7_obj-1","label":"AC-16(07)[01]","text":"a consistent interpretation of security attributes transmitted between distributed system components is provided;"},{"id":"ac-16.7_obj-2","label":"AC-16(07)[02]","text":"a consistent interpretation of privacy attributes transmitted between distributed system components is provided."}],"methods":[{"method":"examine","label":"AC-16(07)-Examine"},{"method":"interview","label":"AC-16(07)-Interview"},{"method":"test","label":"AC-16(07)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(8)","oscal_id":"ac-16.8","family":"AC","title":"Association Techniques and Technologies","statement":"Implement <organization-defined techniques and technologies> in associating security and privacy attributes to information.","supplemental_guidance":"The association of security and privacy attributes to information within systems is important for conducting automated access enforcement and flow enforcement actions. The association of such attributes to information (i.e., binding) can be accomplished with technologies and techniques that provide different levels of assurance. For example, systems can cryptographically bind attributes to information using digital signatures that support cryptographic keys protected by hardware devices (sometimes known as hardware roots of trust).","implementation_level":"system","parameters":[{"id":"ac-16.8_prm_1","label":"organization-defined techniques and technologies"},{"id":"ac-16.08_odp.01","label":"techniques and technologies"},{"id":"ac-16.08_odp.02","label":"techniques and technologies"}],"objectives":[{"id":"ac-16.8_obj-1","label":"AC-16(08)[01]","text":"{{ insert: param, ac-16.08_odp.01 }} are implemented in associating security attributes to information;"},{"id":"ac-16.8_obj-2","label":"AC-16(08)[02]","text":"{{ insert: param, ac-16.08_odp.02 }} are implemented in associating privacy attributes to information."}],"methods":[{"method":"examine","label":"AC-16(08)-Examine"},{"method":"interview","label":"AC-16(08)-Interview"},{"method":"test","label":"AC-16(08)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(9)","oscal_id":"ac-16.9","family":"AC","title":"Attribute Reassignment — Regrading Mechanisms","statement":"Change security and privacy attributes associated with information only via regrading mechanisms validated using <organization-defined techniques or procedures>.","supplemental_guidance":"A regrading mechanism is a trusted process authorized to re-classify and re-label data in accordance with a defined policy exception. Validated regrading mechanisms are used by organizations to provide the requisite levels of assurance for attribute reassignment activities. The validation is facilitated by ensuring that regrading mechanisms are single purpose and of limited function. Since security and privacy attribute changes can directly affect policy enforcement actions, implementing trustworthy regrading mechanisms is necessary to help ensure that such mechanisms perform in a consistent and correct mode of operation.","implementation_level":"organization","parameters":[{"id":"ac-16.9_prm_1","label":"organization-defined techniques or procedures"},{"id":"ac-16.09_odp.01","label":"techniques or procedures"},{"id":"ac-16.09_odp.02","label":"techniques or procedures"}],"objectives":[{"id":"ac-16.9_obj-1","label":"AC-16(09)[01]","text":"security attributes associated with information are changed only via regrading mechanisms validated using {{ insert: param, ac-16.09_odp.01 }};"},{"id":"ac-16.9_obj-2","label":"AC-16(09)[02]","text":"privacy attributes associated with information are changed only via regrading mechanisms validated using {{ insert: param, ac-16.09_odp.02 }}."}],"methods":[{"method":"examine","label":"AC-16(09)-Examine"},{"method":"interview","label":"AC-16(09)-Interview"},{"method":"test","label":"AC-16(09)-Test"}],"is_enhancement":true,"parent_id":"AC-16"},{"id":"AC-16(10)","oscal_id":"ac-16.10","family":"AC","title":"Attribute Configuration by Authorized Individuals","statement":"Provide authorized individuals the capability to define or change the type and value of security and privacy attributes available for association with subjects and objects.","supplemental_guidance":"The content or assigned values of security and privacy attributes can directly affect the ability of individuals to access organizational information. Thus, it is important for systems to be able to limit the ability to create or modify the type and value of attributes available for association with subjects and objects to authorized individuals only.","implementation_level":"organization","objectives":[{"id":"ac-16.10_obj-1","label":"AC-16(10)[01]","text":"authorized individuals are provided with the capability to define or change the type and value of security attributes available for association with subjects and objects;"},{"id":"ac-16.10_obj-2","label":"AC-16(10)[02]","text":"authorized individuals are provided with the capability to define or change the type and value of privacy attributes available for association with subjects and objects."}],"methods":[{"method":"examine","label":"AC-16(10)-Examine"},{"method":"interview","label":"AC-16(10)-Interview"},{"method":"test","label":"AC-16(10)-Test"}],"is_enhancement":true,"parent_id":"AC-16"}]},{"id":"AC-17","oscal_id":"ac-17","family":"AC","title":"Remote Access","statement":"a. Establish and document usage restrictions, configuration/connection requirements, and implementation guidance for each type of remote access allowed; and\nb. Authorize each type of remote access to the system prior to allowing such connections.","supplemental_guidance":"Remote access is access to organizational systems (or processes acting on behalf of users) that communicate through external networks such as the Internet. Types of remote access include dial-up, broadband, and wireless. Organizations use encrypted virtual private networks (VPNs) to enhance confidentiality and integrity for remote connections. The use of encrypted VPNs provides sufficient assurance to the organization that it can effectively treat such connections as internal networks if the cryptographic mechanisms used are implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Still, VPN connections traverse external networks, and the encrypted VPN does not enhance the availability of remote connections. VPNs with encrypted tunnels can also affect the ability to adequately monitor network communications traffic for malicious code. Remote access controls apply to systems other than public web servers or systems designed for public access. Authorization of each remote access type addresses authorization prior to allowing remote access without specifying the specific formats for such authorization. While organizations may use information exchange and system connection security agreements to manage remote access connections to other systems, such agreements are addressed as part of [CA-3](#ca-3) . Enforcing access restrictions for remote access is addressed via [AC-3](#ac-3).","implementation_level":"organization","objectives":[{"id":"ac-17_obj.a-1","label":"AC-17a.[01]","text":"usage restrictions are established and documented for each type of remote access allowed;"},{"id":"ac-17_obj.a-2","label":"AC-17a.[02]","text":"configuration/connection requirements are established and documented for each type of remote access allowed;"},{"id":"ac-17_obj.a-3","label":"AC-17a.[03]","text":"implementation guidance is established and documented for each type of remote access allowed;"},{"id":"ac-17_obj.b","label":"AC-17b.","text":"each type of remote access to the system is authorized prior to allowing such connections."}],"methods":[{"method":"examine","label":"AC-17-Examine"},{"method":"interview","label":"AC-17-Interview"},{"method":"test","label":"AC-17-Test"}],"references":[{"title":"SP 800-46"},{"title":"SP 800-77"},{"title":"SP 800-113"},{"title":"SP 800-114"},{"title":"SP 800-121"},{"title":"IR 7966"}],"related_controls":["AC-2","AC-3","AC-4","AC-18","AC-19","AC-20","CA-3","CM-10","IA-2","IA-3","IA-8","MA-4","PE-17","PL-2","PL-4","SC-10","SC-12","SC-13","SI-4"],"enhancements":[{"id":"AC-17(1)","oscal_id":"ac-17.1","family":"AC","title":"Monitoring and Control","statement":"Employ automated mechanisms to monitor and control remote access methods.","supplemental_guidance":"Monitoring and control of remote access methods allows organizations to detect attacks and help ensure compliance with remote access policies by auditing the connection activities of remote users on a variety of system components, including servers, notebook computers, workstations, smart phones, and tablets. Audit logging for remote access is enforced by [AU-2](#au-2) . Audit events are defined in [AU-2a](#au-2_smt.a).","implementation_level":"organization","objectives":[{"id":"ac-17.1_obj-1","label":"AC-17(01)[01]","text":"automated mechanisms are employed to monitor remote access methods;"},{"id":"ac-17.1_obj-2","label":"AC-17(01)[02]","text":"automated mechanisms are employed to control remote access methods."}],"methods":[{"method":"examine","label":"AC-17(01)-Examine"},{"method":"interview","label":"AC-17(01)-Interview"},{"method":"test","label":"AC-17(01)-Test"}],"related_controls":["AU-2","AU-6","AU-12","AU-14"],"is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(2)","oscal_id":"ac-17.2","family":"AC","title":"Protection of Confidentiality and Integrity Using Encryption","statement":"Implement cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions.","supplemental_guidance":"Virtual private networks can be used to protect the confidentiality and integrity of remote access sessions. Transport Layer Security (TLS) is an example of a cryptographic protocol that provides end-to-end communications security over networks and is used for Internet communications and online transactions.","implementation_level":"system","methods":[{"method":"examine","label":"AC-17(02)-Examine"},{"method":"interview","label":"AC-17(02)-Interview"},{"method":"test","label":"AC-17(02)-Test"}],"related_controls":["SC-8","SC-12","SC-13"],"is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(3)","oscal_id":"ac-17.3","family":"AC","title":"Managed Access Control Points","statement":"Route remote accesses through authorized and managed network access control points.","supplemental_guidance":"Organizations consider the Trusted Internet Connections (TIC) initiative [DHS TIC](#4f42ee6e-86cc-403b-a51f-76c2b4f81b54) requirements for external network connections since limiting the number of access control points for remote access reduces attack surfaces.","implementation_level":"system","methods":[{"method":"examine","label":"AC-17(03)-Examine"},{"method":"interview","label":"AC-17(03)-Interview"},{"method":"test","label":"AC-17(03)-Test"}],"related_controls":["SC-7"],"is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(4)","oscal_id":"ac-17.4","family":"AC","title":"Privileged Commands and Access","statement":"(a) Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and for the following needs: <organization-defined needs> ; and\n(b) Document the rationale for remote access in the security plan for the system.","supplemental_guidance":"Remote access to systems represents a significant potential vulnerability that can be exploited by adversaries. As such, restricting the execution of privileged commands and access to security-relevant information via remote access reduces the exposure of the organization and the susceptibility to threats by adversaries to the remote access capability.","implementation_level":"organization","parameters":[{"id":"ac-17.4_prm_1","label":"organization-defined needs"},{"id":"ac-17.04_odp.01","label":"needs requiring remote access"},{"id":"ac-17.04_odp.02","label":"needs requiring remote access"}],"objectives":[{"id":"ac-17.4_obj.a-1","label":"AC-17(04)(a)[01]","text":"the execution of privileged commands via remote access is authorized only in a format that provides assessable evidence;"},{"id":"ac-17.4_obj.a-2","label":"AC-17(04)(a)[02]","text":"access to security-relevant information via remote access is authorized only in a format that provides assessable evidence;"},{"id":"ac-17.4_obj.a-3","label":"AC-17(04)(a)[03]","text":"the execution of privileged commands via remote access is authorized only for the following needs: {{ insert: param, ac-17.04_odp.01 }};"},{"id":"ac-17.4_obj.a-4","label":"AC-17(04)(a)[04]","text":"access to security-relevant information via remote access is authorized only for the following needs: {{ insert: param, ac-17.04_odp.02 }};"},{"id":"ac-17.4_obj.b","label":"AC-17(04)(b)","text":"the rationale for remote access is documented in the security plan for the system."}],"methods":[{"method":"examine","label":"AC-17(04)-Examine"},{"method":"interview","label":"AC-17(04)-Interview"},{"method":"test","label":"AC-17(04)-Test"}],"related_controls":["AC-6","SC-12","SC-13"],"is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(5)","oscal_id":"ac-17.5","family":"AC","title":"Monitoring for Unauthorized Connections","statement":"","is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(6)","oscal_id":"ac-17.6","family":"AC","title":"Protection of Mechanism Information","statement":"Protect information about remote access mechanisms from unauthorized use and disclosure.","supplemental_guidance":"Remote access to organizational information by non-organizational entities can increase the risk of unauthorized use and disclosure about remote access mechanisms. The organization considers including remote access requirements in the information exchange agreements with other organizations, as applicable. Remote access requirements can also be included in rules of behavior (see [PL-4](#pl-4) ) and access agreements (see [PS-6](#ps-6)).","implementation_level":"organization","methods":[{"method":"examine","label":"AC-17(06)-Examine"},{"method":"interview","label":"AC-17(06)-Interview"}],"related_controls":["AT-2","AT-3","PS-6"],"is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(7)","oscal_id":"ac-17.7","family":"AC","title":"Additional Protection for Security Function Access","statement":"","is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(8)","oscal_id":"ac-17.8","family":"AC","title":"Disable Nonsecure Network Protocols","statement":"","is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(9)","oscal_id":"ac-17.9","family":"AC","title":"Disconnect or Disable Access","statement":"Provide the capability to disconnect or disable remote access to the system within <time period>.","supplemental_guidance":"The speed of system disconnect or disablement varies based on the criticality of missions or business functions and the need to eliminate immediate or future remote access to systems.","implementation_level":"organization","parameters":[{"id":"ac-17.09_odp","label":"time period"}],"methods":[{"method":"examine","label":"AC-17(09)-Examine"},{"method":"interview","label":"AC-17(09)-Interview"},{"method":"test","label":"AC-17(09)-Test"}],"is_enhancement":true,"parent_id":"AC-17"},{"id":"AC-17(10)","oscal_id":"ac-17.10","family":"AC","title":"Authenticate Remote Commands","statement":"Implement <mechanisms> to authenticate <remote commands>.","supplemental_guidance":"Authenticating remote commands protects against unauthorized commands and the replay of authorized commands. The ability to authenticate remote commands is important for remote systems for which loss, malfunction, misdirection, or exploitation would have immediate or serious consequences, such as injury, death, property damage, loss of high value assets, failure of mission or business functions, or compromise of classified or controlled unclassified information. Authentication mechanisms for remote commands ensure that systems accept and execute commands in the order intended, execute only authorized commands, and reject unauthorized commands. Cryptographic mechanisms can be used, for example, to authenticate remote commands.","implementation_level":"system","parameters":[{"id":"ac-17.10_odp.01","label":"mechanisms"},{"id":"ac-17.10_odp.02","label":"remote commands"}],"methods":[{"method":"examine","label":"AC-17(10)-Examine"},{"method":"interview","label":"AC-17(10)-Interview"},{"method":"test","label":"AC-17(10)-Test"}],"related_controls":["SC-12","SC-13","SC-23"],"is_enhancement":true,"parent_id":"AC-17"}]},{"id":"AC-18","oscal_id":"ac-18","family":"AC","title":"Wireless Access","statement":"a. Establish configuration requirements, connection requirements, and implementation guidance for each type of wireless access; and\nb. Authorize each type of wireless access to the system prior to allowing such connections.","supplemental_guidance":"Wireless technologies include microwave, packet radio (ultra-high frequency or very high frequency), 802.11x, and Bluetooth. Wireless networks use authentication protocols that provide authenticator protection and mutual authentication.","implementation_level":"organization","objectives":[{"id":"ac-18_obj.a-1","label":"AC-18a.[01]","text":"configuration requirements are established for each type of wireless access;"},{"id":"ac-18_obj.a-2","label":"AC-18a.[02]","text":"connection requirements are established for each type of wireless access;"},{"id":"ac-18_obj.a-3","label":"AC-18a.[03]","text":"implementation guidance is established for each type of wireless access;"},{"id":"ac-18_obj.b","label":"AC-18b.","text":"each type of wireless access to the system is authorized prior to allowing such connections."}],"methods":[{"method":"examine","label":"AC-18-Examine"},{"method":"interview","label":"AC-18-Interview"},{"method":"test","label":"AC-18-Test"}],"references":[{"title":"SP 800-94"},{"title":"SP 800-97"}],"related_controls":["AC-2","AC-3","AC-17","AC-19","CA-9","CM-7","IA-2","IA-3","IA-8","PL-4","SC-40","SC-43","SI-4"],"enhancements":[{"id":"AC-18(1)","oscal_id":"ac-18.1","family":"AC","title":"Authentication and Encryption","statement":"Protect wireless access to the system using authentication of <organization-defined parameter> and encryption.","supplemental_guidance":"Wireless networking capabilities represent a significant potential vulnerability that can be exploited by adversaries. To protect systems with wireless access points, strong authentication of users and devices along with strong encryption can reduce susceptibility to threats by adversaries involving wireless technologies.","implementation_level":"system","parameters":[{"id":"ac-18.01_odp","label":"","choices":["users","devices"],"how_many":"one-or-more"}],"objectives":[{"id":"ac-18.1_obj-1","label":"AC-18(01)[01]","text":"wireless access to the system is protected using authentication of {{ insert: param, ac-18.01_odp }};"},{"id":"ac-18.1_obj-2","label":"AC-18(01)[02]","text":"wireless access to the system is protected using encryption."}],"methods":[{"method":"examine","label":"AC-18(01)-Examine"},{"method":"interview","label":"AC-18(01)-Interview"},{"method":"test","label":"AC-18(01)-Test"}],"related_controls":["SC-8","SC-12","SC-13"],"is_enhancement":true,"parent_id":"AC-18"},{"id":"AC-18(2)","oscal_id":"ac-18.2","family":"AC","title":"Monitoring Unauthorized Connections","statement":"","is_enhancement":true,"parent_id":"AC-18"},{"id":"AC-18(3)","oscal_id":"ac-18.3","family":"AC","title":"Disable Wireless Networking","statement":"Disable, when not intended for use, wireless networking capabilities embedded within system components prior to issuance and deployment.","supplemental_guidance":"Wireless networking capabilities that are embedded within system components represent a significant potential vulnerability that can be exploited by adversaries. Disabling wireless capabilities when not needed for essential organizational missions or functions can reduce susceptibility to threats by adversaries involving wireless technologies.","implementation_level":"organization","methods":[{"method":"examine","label":"AC-18(03)-Examine"},{"method":"interview","label":"AC-18(03)-Interview"},{"method":"test","label":"AC-18(03)-Test"}],"is_enhancement":true,"parent_id":"AC-18"},{"id":"AC-18(4)","oscal_id":"ac-18.4","family":"AC","title":"Restrict Configurations by Users","statement":"Identify and explicitly authorize users allowed to independently configure wireless networking capabilities.","supplemental_guidance":"Organizational authorizations to allow selected users to configure wireless networking capabilities are enforced, in part, by the access enforcement mechanisms employed within organizational systems.","implementation_level":"organization","objectives":[{"id":"ac-18.4_obj-1","label":"AC-18(04)[01]","text":"users allowed to independently configure wireless networking capabilities are identified;"},{"id":"ac-18.4_obj-2","label":"AC-18(04)[02]","text":"users allowed to independently configure wireless networking capabilities are explicitly authorized."}],"methods":[{"method":"examine","label":"AC-18(04)-Examine"},{"method":"interview","label":"AC-18(04)-Interview"},{"method":"test","label":"AC-18(04)-Test"}],"related_controls":["SC-7","SC-15"],"is_enhancement":true,"parent_id":"AC-18"},{"id":"AC-18(5)","oscal_id":"ac-18.5","family":"AC","title":"Antennas and Transmission Power Levels","statement":"Select radio antennas and calibrate transmission power levels to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries.","supplemental_guidance":"Actions that may be taken to limit unauthorized use of wireless communications outside of organization-controlled boundaries include reducing the power of wireless transmissions so that the transmissions are less likely to emit a signal that can be captured outside of the physical perimeters of the organization, employing measures such as emissions security to control wireless emanations, and using directional or beamforming antennas that reduce the likelihood that unintended receivers will be able to intercept signals. Prior to taking such mitigating actions, organizations can conduct periodic wireless surveys to understand the radio frequency profile of organizational systems as well as other systems that may be operating in the area.","implementation_level":"organization","objectives":[{"id":"ac-18.5_obj-1","label":"AC-18(05)[01]","text":"radio antennas are selected to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries;"},{"id":"ac-18.5_obj-2","label":"AC-18(05)[02]","text":"transmission power levels are calibrated to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries."}],"methods":[{"method":"examine","label":"AC-18(05)-Examine"},{"method":"interview","label":"AC-18(05)-Interview"},{"method":"test","label":"AC-18(05)-Test"}],"related_controls":["PE-19"],"is_enhancement":true,"parent_id":"AC-18"}]},{"id":"AC-19","oscal_id":"ac-19","family":"AC","title":"Access Control for Mobile Devices","statement":"a. Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas; and\nb. Authorize the connection of mobile devices to organizational systems.","supplemental_guidance":"A mobile device is a computing device that has a small form factor such that it can easily be carried by a single individual; is designed to operate without a physical connection; possesses local, non-removable or removable data storage; and includes a self-contained power source. Mobile device functionality may also include voice communication capabilities, on-board sensors that allow the device to capture information, and/or built-in features for synchronizing local data with remote locations. Examples include smart phones and tablets. Mobile devices are typically associated with a single individual. The processing, storage, and transmission capability of the mobile device may be comparable to or merely a subset of notebook/desktop systems, depending on the nature and intended purpose of the device. Protection and control of mobile devices is behavior or policy-based and requires users to take physical action to protect and control such devices when outside of controlled areas. Controlled areas are spaces for which organizations provide physical or procedural controls to meet the requirements established for protecting information and systems.\n\nDue to the large variety of mobile devices with different characteristics and capabilities, organizational restrictions may vary for the different classes or types of such devices. Usage restrictions and specific implementation guidance for mobile devices include configuration management, device identification and authentication, implementation of mandatory protective software, scanning devices for malicious code, updating virus protection software, scanning for critical software updates and patches, conducting primary operating system (and possibly other resident software) integrity checks, and disabling unnecessary hardware.\n\nUsage restrictions and authorization to connect may vary among organizational systems. For example, the organization may authorize the connection of mobile devices to its network and impose a set of usage restrictions, while a system owner may withhold authorization for mobile device connection to specific applications or impose additional usage restrictions before allowing mobile device connections to a system. Adequate security for mobile devices goes beyond the requirements specified in [AC-19](#ac-19) . Many safeguards for mobile devices are reflected in other controls. [AC-20](#ac-20) addresses mobile devices that are not organization-controlled.","implementation_level":"organization","objectives":[{"id":"ac-19_obj.a-1","label":"AC-19a.[01]","text":"configuration requirements are established for organization-controlled mobile devices, including when such devices are outside of the controlled area;"},{"id":"ac-19_obj.a-2","label":"AC-19a.[02]","text":"connection requirements are established for organization-controlled mobile devices, including when such devices are outside of the controlled area;"},{"id":"ac-19_obj.a-3","label":"AC-19a.[03]","text":"implementation guidance is established for organization-controlled mobile devices, including when such devices are outside of the controlled area;"},{"id":"ac-19_obj.b","label":"AC-19b.","text":"the connection of mobile devices to organizational systems is authorized."}],"methods":[{"method":"examine","label":"AC-19-Examine"},{"method":"interview","label":"AC-19-Interview"},{"method":"test","label":"AC-19-Test"}],"references":[{"title":"SP 800-114"},{"title":"SP 800-124"}],"related_controls":["AC-3","AC-4","AC-7","AC-11","AC-17","AC-18","AC-20","CA-9","CM-2","CM-6","IA-2","IA-3","MP-2","MP-4","MP-5","MP-7","PL-4","SC-7","SC-34","SC-43","SI-3","SI-4"],"enhancements":[{"id":"AC-19(1)","oscal_id":"ac-19.1","family":"AC","title":"Use of Writable and Portable Storage Devices","statement":"","is_enhancement":true,"parent_id":"AC-19"},{"id":"AC-19(2)","oscal_id":"ac-19.2","family":"AC","title":"Use of Personally Owned Portable Storage Devices","statement":"","is_enhancement":true,"parent_id":"AC-19"},{"id":"AC-19(3)","oscal_id":"ac-19.3","family":"AC","title":"Use of Portable Storage Devices with No Identifiable Owner","statement":"","is_enhancement":true,"parent_id":"AC-19"},{"id":"AC-19(4)","oscal_id":"ac-19.4","family":"AC","title":"Restrictions for Classified Information","statement":"(a) Prohibit the use of unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and\n(b) Enforce the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information:\n  Enforce the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information:\n  (1) Connection of unclassified mobile devices to classified systems is prohibited;\n  (2) Connection of unclassified mobile devices to unclassified systems requires approval from the authorizing official;\n  (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and\n  (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by <security officials> , and if classified information is found, the incident handling policy is followed.\n(c) Restrict the connection of classified mobile devices to classified systems in accordance with <security policies>.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"ac-19.04_odp.01","label":"security officials"},{"id":"ac-19.04_odp.02","label":"security policies"}],"objectives":[{"id":"ac-19.4_obj.a","label":"AC-19(04)(a)","text":"the use of unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information is prohibited unless specifically permitted by the authorizing official;"},{"id":"ac-19.4_obj.b.1","label":"AC-19(04)(b)(01)","text":"prohibition of the connection of unclassified mobile devices to classified systems is enforced on individuals permitted by an authorizing official to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information;"},{"id":"ac-19.4_obj.b.2","label":"AC-19(04)(b)(02)","text":"approval by the authorizing official for the connection of unclassified mobile devices to unclassified systems is enforced on individuals permitted to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information;"},{"id":"ac-19.4_obj.b.3","label":"AC-19(04)(b)(03)","text":"prohibition of the use of internal or external modems or wireless interfaces within unclassified mobile devices is enforced on individuals permitted by an authorizing official to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information;"},{"id":"ac-19.4_obj.b.4-1","label":"AC-19(04)(b)(04)[01]","text":"random review and inspection of unclassified mobile devices and the information stored on those devices by {{ insert: param, ac-19.04_odp.01 }} are enforced;"},{"id":"ac-19.4_obj.b.4-2","label":"AC-19(04)(b)(04)[02]","text":"following of the incident handling policy is enforced if classified information is found during a random review and inspection of unclassified mobile devices;"},{"id":"ac-19.4_obj.c","label":"AC-19(04)(c)","text":"the connection of classified mobile devices to classified systems is restricted in accordance with {{ insert: param, ac-19.04_odp.02 }}."}],"methods":[{"method":"examine","label":"AC-19(04)-Examine"},{"method":"interview","label":"AC-19(04)-Interview"},{"method":"test","label":"AC-19(04)-Test"}],"related_controls":["CM-8","IR-4"],"is_enhancement":true,"parent_id":"AC-19"},{"id":"AC-19(5)","oscal_id":"ac-19.5","family":"AC","title":"Full Device or Container-based Encryption","statement":"Employ <organization-defined parameter> to protect the confidentiality and integrity of information on <mobile devices>.","supplemental_guidance":"Container-based encryption provides a more fine-grained approach to data and information encryption on mobile devices, including encrypting selected data structures such as files, records, or fields.","implementation_level":"organization","parameters":[{"id":"ac-19.05_odp.01","label":"","choices":["full-device encryption","container-based encryption"]},{"id":"ac-19.05_odp.02","label":"mobile devices"}],"methods":[{"method":"examine","label":"AC-19(05)-Examine"},{"method":"interview","label":"AC-19(05)-Interview"},{"method":"test","label":"AC-19(05)-Test"}],"related_controls":["SC-12","SC-13","SC-28"],"is_enhancement":true,"parent_id":"AC-19"}]},{"id":"AC-20","oscal_id":"ac-20","family":"AC","title":"Use of External Systems","statement":"a. <organization-defined parameter> , consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:\n  <organization-defined parameter> , consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:\n  1. Access the system from external systems; and\n  2. Process, store, or transmit organization-controlled information using external systems; or\nb. Prohibit the use of <prohibited types of external systems>.","supplemental_guidance":"External systems are systems that are used by but not part of organizational systems, and for which the organization has no direct control over the implementation of required controls or the assessment of control effectiveness. External systems include personally owned systems, components, or devices; privately owned computing and communications devices in commercial or public facilities; systems owned or controlled by nonfederal organizations; systems managed by contractors; and federal information systems that are not owned by, operated by, or under the direct supervision or authority of the organization. External systems also include systems owned or operated by other components within the same organization and systems within the organization with different authorization boundaries. Organizations have the option to prohibit the use of any type of external system or prohibit the use of specified types of external systems, (e.g., prohibit the use of any external system that is not organizationally owned or prohibit the use of personally-owned systems).\n\nFor some external systems (i.e., systems operated by other organizations), the trust relationships that have been established between those organizations and the originating organization may be such that no explicit terms and conditions are required. Systems within these organizations may not be considered external. These situations occur when, for example, there are pre-existing information exchange agreements (either implicit or explicit) established between organizations or components or when such agreements are specified by applicable laws, executive orders, directives, regulations, policies, or standards. Authorized individuals include organizational personnel, contractors, or other individuals with authorized access to organizational systems and over which organizations have the authority to impose specific rules of behavior regarding system access. Restrictions that organizations impose on authorized individuals need not be uniform, as the restrictions may vary depending on trust relationships between organizations. Therefore, organizations may choose to impose different security restrictions on contractors than on state, local, or tribal governments.\n\nExternal systems used to access public interfaces to organizational systems are outside the scope of [AC-20](#ac-20) . Organizations establish specific terms and conditions for the use of external systems in accordance with organizational security policies and procedures. At a minimum, terms and conditions address the specific types of applications that can be accessed on organizational systems from external systems and the highest security category of information that can be processed, stored, or transmitted on external systems. If the terms and conditions with the owners of the external systems cannot be established, organizations may impose restrictions on organizational personnel using those external systems.","implementation_level":"organization","parameters":[{"id":"ac-20_odp.01","label":"","choices":["establish {{ insert: param, ac-20_odp.02 }} ","identify {{ insert: param, ac-20_odp.03 }} "],"how_many":"one-or-more"},{"id":"ac-20_odp.02","label":"terms and conditions"},{"id":"ac-20_odp.03","label":"controls asserted"},{"id":"ac-20_odp.04","label":"prohibited types of external systems"}],"objectives":[{"id":"ac-20_obj.a.1","label":"AC-20a.01","text":"{{ insert: param, ac-20_odp.01 }} is/are consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to access the system from external systems (if applicable);"},{"id":"ac-20_obj.a.2","label":"AC-20a.02","text":"{{ insert: param, ac-20_odp.01 }} is/are consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to process, store, or transmit organization-controlled information using external systems (if applicable);"},{"id":"ac-20_obj.b","label":"AC-20b.","text":"the use of {{ insert: param, ac-20_odp.04 }} is prohibited (if applicable)."}],"methods":[{"method":"examine","label":"AC-20-Examine"},{"method":"interview","label":"AC-20-Interview"},{"method":"test","label":"AC-20-Test"}],"references":[{"title":"FIPS 199"},{"title":"SP 800-171"},{"title":"SP 800-172"}],"related_controls":["AC-2","AC-3","AC-17","AC-19","CA-3","PL-2","PL-4","SA-9","SC-7"],"enhancements":[{"id":"AC-20(1)","oscal_id":"ac-20.1","family":"AC","title":"Limits on Authorized Use","statement":"Permit authorized individuals to use an external system to access the system or to process, store, or transmit organization-controlled information only after:\n(a) Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or\n(b) Retention of approved system connection or processing agreements with the organizational entity hosting the external system.","supplemental_guidance":"Limiting authorized use recognizes circumstances where individuals using external systems may need to access organizational systems. Organizations need assurance that the external systems contain the necessary controls so as not to compromise, damage, or otherwise harm organizational systems. Verification that the required controls have been implemented can be achieved by external, independent assessments, attestations, or other means, depending on the confidence level required by organizations.","implementation_level":"organization","objectives":[{"id":"ac-20.1_obj.a","label":"AC-20(01)(a)","text":"authorized individuals are permitted to use an external system to access the system or to process, store, or transmit organization-controlled information only after verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans (if applicable);"},{"id":"ac-20.1_obj.b","label":"AC-20(01)(b)","text":"authorized individuals are permitted to use an external system to access the system or to process, store, or transmit organization-controlled information only after retention of approved system connection or processing agreements with the organizational entity hosting the external system (if applicable)."}],"methods":[{"method":"examine","label":"AC-20(01)-Examine"},{"method":"interview","label":"AC-20(01)-Interview"},{"method":"test","label":"AC-20(01)-Test"}],"related_controls":["CA-2"],"is_enhancement":true,"parent_id":"AC-20"},{"id":"AC-20(2)","oscal_id":"ac-20.2","family":"AC","title":"Portable Storage Devices — Restricted Use","statement":"Restrict the use of organization-controlled portable storage devices by authorized individuals on external systems using <restrictions>.","supplemental_guidance":"Limits on the use of organization-controlled portable storage devices in external systems include restrictions on how the devices may be used and under what conditions the devices may be used.","implementation_level":"organization","parameters":[{"id":"ac-20.02_odp","label":"restrictions"}],"methods":[{"method":"examine","label":"AC-20(02)-Examine"},{"method":"interview","label":"AC-20(02)-Interview"},{"method":"test","label":"AC-20(02)-Test"}],"related_controls":["MP-7","SC-41"],"is_enhancement":true,"parent_id":"AC-20"},{"id":"AC-20(3)","oscal_id":"ac-20.3","family":"AC","title":"Non-organizationally Owned Systems — Restricted Use","statement":"Restrict the use of non-organizationally owned systems or system components to process, store, or transmit organizational information using <restrictions>.","supplemental_guidance":"Non-organizationally owned systems or system components include systems or system components owned by other organizations as well as personally owned devices. There are potential risks to using non-organizationally owned systems or components. In some cases, the risk is sufficiently high as to prohibit such use (see [AC-20 b.](#ac-20_smt.b) ). In other cases, the use of such systems or system components may be allowed but restricted in some way. Restrictions include requiring the implementation of approved controls prior to authorizing the connection of non-organizationally owned systems and components; limiting access to types of information, services, or applications; using virtualization techniques to limit processing and storage activities to servers or system components provisioned by the organization; and agreeing to the terms and conditions for usage. Organizations consult with the Office of the General Counsel regarding legal issues associated with using personally owned devices, including requirements for conducting forensic analyses during investigations after an incident.","implementation_level":"organization","parameters":[{"id":"ac-20.03_odp","label":"restrictions"}],"methods":[{"method":"examine","label":"AC-20(03)-Examine"},{"method":"interview","label":"AC-20(03)-Interview"},{"method":"test","label":"AC-20(03)-Test"}],"is_enhancement":true,"parent_id":"AC-20"},{"id":"AC-20(4)","oscal_id":"ac-20.4","family":"AC","title":"Network Accessible Storage Devices — Prohibited Use","statement":"Prohibit the use of <network-accessible storage devices> in external systems.","supplemental_guidance":"Network-accessible storage devices in external systems include online storage devices in public, hybrid, or community cloud-based systems.","implementation_level":"organization","parameters":[{"id":"ac-20.04_odp","label":"network-accessible storage devices"}],"methods":[{"method":"examine","label":"AC-20(04)-Examine"},{"method":"interview","label":"AC-20(04)-Interview"},{"method":"test","label":"AC-20(04)-Test"}],"is_enhancement":true,"parent_id":"AC-20"},{"id":"AC-20(5)","oscal_id":"ac-20.5","family":"AC","title":"Portable Storage Devices — Prohibited Use","statement":"Prohibit the use of organization-controlled portable storage devices by authorized individuals on external systems.","supplemental_guidance":"Limits on the use of organization-controlled portable storage devices in external systems include a complete prohibition of the use of such devices. Prohibiting such use is enforced using technical methods and/or nontechnical (i.e., process-based) methods.","implementation_level":"organization","methods":[{"method":"examine","label":"AC-20(05)-Examine"},{"method":"interview","label":"AC-20(05)-Interview"}],"related_controls":["MP-7","PL-4","PS-6","SC-41"],"is_enhancement":true,"parent_id":"AC-20"}]},{"id":"AC-21","oscal_id":"ac-21","family":"AC","title":"Information Sharing","statement":"a. Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for <information-sharing circumstances> ; and\nb. Employ <automated mechanisms> to assist users in making information sharing and collaboration decisions.","supplemental_guidance":"Information sharing applies to information that may be restricted in some manner based on some formal or administrative determination. Examples of such information include, contract-sensitive information, classified information related to special access programs or compartments, privileged information, proprietary information, and personally identifiable information. Security and privacy risk assessments as well as applicable laws, regulations, and policies can provide useful inputs to these determinations. Depending on the circumstances, sharing partners may be defined at the individual, group, or organizational level. Information may be defined by content, type, security category, or special access program or compartment. Access restrictions may include non-disclosure agreements (NDA). Information flow techniques and security attributes may be used to provide automated assistance to users making sharing and collaboration decisions.","implementation_level":"organization","parameters":[{"id":"ac-21_odp.01","label":"information-sharing circumstances"},{"id":"ac-21_odp.02","label":"automated mechanisms"}],"objectives":[{"id":"ac-21_obj.a","label":"AC-21a.","text":"authorized users are enabled to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for {{ insert: param, ac-21_odp.01 }};"},{"id":"ac-21_obj.b","label":"AC-21b.","text":"{{ insert: param, ac-21_odp.02 }} are employed to assist users in making information-sharing and collaboration decisions."}],"methods":[{"method":"examine","label":"AC-21-Examine"},{"method":"interview","label":"AC-21-Interview"},{"method":"test","label":"AC-21-Test"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-150"},{"title":"IR 8062"}],"related_controls":["AC-3","AC-4","AC-16","PT-2","PT-7","RA-3","SC-15"],"enhancements":[{"id":"AC-21(1)","oscal_id":"ac-21.1","family":"AC","title":"Automated Decision Support","statement":"Employ <automated mechanisms> to enforce information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared.","supplemental_guidance":"Automated mechanisms are used to enforce information sharing decisions.","implementation_level":"system","parameters":[{"id":"ac-21.01_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"AC-21(01)-Examine"},{"method":"interview","label":"AC-21(01)-Interview"},{"method":"test","label":"AC-21(01)-Test"}],"is_enhancement":true,"parent_id":"AC-21"},{"id":"AC-21(2)","oscal_id":"ac-21.2","family":"AC","title":"Information Search and Retrieval","statement":"Implement information search and retrieval services that enforce <information-sharing restrictions>.","supplemental_guidance":"Information search and retrieval services identify information system resources relevant to an information need.","implementation_level":"system","parameters":[{"id":"ac-21.02_odp","label":"information-sharing restrictions"}],"methods":[{"method":"examine","label":"AC-21(02)-Examine"},{"method":"interview","label":"AC-21(02)-Interview"},{"method":"test","label":"AC-21(02)-Test"}],"is_enhancement":true,"parent_id":"AC-21"}]},{"id":"AC-22","oscal_id":"ac-22","family":"AC","title":"Publicly Accessible Content","statement":"a. Designate individuals authorized to make information publicly accessible;\nb. Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information;\nc. Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; and\nd. Review the content on the publicly accessible system for nonpublic information <frequency> and remove such information, if discovered.","supplemental_guidance":"In accordance with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines, the public is not authorized to have access to nonpublic information, including information protected under the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) and proprietary information. Publicly accessible content addresses systems that are controlled by the organization and accessible to the public, typically without identification or authentication. Posting information on non-organizational systems (e.g., non-organizational public websites, forums, and social media) is covered by organizational policy. While organizations may have individuals who are responsible for developing and implementing policies about the information that can be made publicly accessible, publicly accessible content addresses the management of the individuals who make such information publicly accessible.","implementation_level":"organization","parameters":[{"id":"ac-22_odp","label":"frequency"}],"objectives":[{"id":"ac-22_obj.a","label":"AC-22a.","text":"designated individuals are authorized to make information publicly accessible;"},{"id":"ac-22_obj.b","label":"AC-22b.","text":"authorized individuals are trained to ensure that publicly accessible information does not contain non-public information;"},{"id":"ac-22_obj.c","label":"AC-22c.","text":"the proposed content of information is reviewed prior to posting onto the publicly accessible system to ensure that non-public information is not included;"},{"id":"ac-22_obj.d-1","label":"AC-22d.[01]","text":"the content on the publicly accessible system is reviewed for non-public information {{ insert: param, ac-22_odp }};"},{"id":"ac-22_obj.d-2","label":"AC-22d.[02]","text":"non-public information is removed from the publicly accessible system, if discovered."}],"methods":[{"method":"examine","label":"AC-22-Examine"},{"method":"interview","label":"AC-22-Interview"},{"method":"test","label":"AC-22-Test"}],"references":[{"title":"PRIVACT"}],"related_controls":["AC-3","AT-2","AT-3","AU-13"]},{"id":"AC-23","oscal_id":"ac-23","family":"AC","title":"Data Mining Protection","statement":"Employ <techniques> for <data storage objects> to detect and protect against unauthorized data mining.","supplemental_guidance":"Data mining is an analytical process that attempts to find correlations or patterns in large data sets for the purpose of data or knowledge discovery. Data storage objects include database records and database fields. Sensitive information can be extracted from data mining operations. When information is personally identifiable information, it may lead to unanticipated revelations about individuals and give rise to privacy risks. Prior to performing data mining activities, organizations determine whether such activities are authorized. Organizations may be subject to applicable laws, executive orders, directives, regulations, or policies that address data mining requirements. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements.\n\nData mining prevention and detection techniques include limiting the number and frequency of database queries to increase the work factor needed to determine the contents of databases, limiting types of responses provided to database queries, applying differential privacy techniques or homomorphic encryption, and notifying personnel when atypical database queries or accesses occur. Data mining protection focuses on protecting information from data mining while such information resides in organizational data stores. In contrast, [AU-13](#au-13) focuses on monitoring for organizational information that may have been mined or otherwise obtained from data stores and is available as open-source information residing on external sites, such as social networking or social media websites.\n\n[EO 13587](#0af071a6-cf8e-48ee-8c82-fe91efa20f94) requires the establishment of an insider threat program for deterring, detecting, and mitigating insider threats, including the safeguarding of sensitive information from exploitation, compromise, or other unauthorized disclosure. Data mining protection requires organizations to identify appropriate techniques to prevent and detect unnecessary or unauthorized data mining. Data mining can be used by an insider to collect organizational information for the purpose of exfiltration.","implementation_level":"organization","parameters":[{"id":"ac-23_odp.01","label":"techniques"},{"id":"ac-23_odp.02","label":"data storage objects"}],"methods":[{"method":"examine","label":"AC-23-Examine"},{"method":"interview","label":"AC-23-Interview"},{"method":"test","label":"AC-23-Test"}],"references":[{"title":"EO 13587"}],"related_controls":["PM-12","PT-2"]},{"id":"AC-24","oscal_id":"ac-24","family":"AC","title":"Access Control Decisions","statement":"<organization-defined parameter> to ensure <access control decisions> are applied to each access request prior to access enforcement.","supplemental_guidance":"Access control decisions (also known as authorization decisions) occur when authorization information is applied to specific accesses. In contrast, access enforcement occurs when systems enforce access control decisions. While it is common to have access control decisions and access enforcement implemented by the same entity, it is not required, and it is not always an optimal implementation choice. For some architectures and distributed systems, different entities may make access control decisions and enforce access.","implementation_level":"organization","parameters":[{"id":"ac-24_odp.01","label":"","choices":["establish procedures","implement mechanisms"],"how_many":"one-or-more"},{"id":"ac-24_odp.02","label":"access control decisions"}],"methods":[{"method":"examine","label":"AC-24-Examine"},{"method":"interview","label":"AC-24-Interview"},{"method":"test","label":"AC-24-Test"}],"references":[{"title":"SP 800-162"},{"title":"SP 800-178"}],"related_controls":["AC-2","AC-3"],"enhancements":[{"id":"AC-24(1)","oscal_id":"ac-24.1","family":"AC","title":"Transmit Access Authorization Information","statement":"Transmit <access authorization information> using <controls> to <systems> that enforce access control decisions.","supplemental_guidance":"Authorization processes and access control decisions may occur in separate parts of systems or in separate systems. In such instances, authorization information is transmitted securely (e.g., using cryptographic mechanisms) so that timely access control decisions can be enforced at the appropriate locations. To support the access control decisions, it may be necessary to transmit as part of the access authorization information supporting security and privacy attributes. This is because in distributed systems, there are various access control decisions that need to be made, and different entities make these decisions in a serial fashion, each requiring those attributes to make the decisions. Protecting access authorization information ensures that such information cannot be altered, spoofed, or compromised during transmission.","implementation_level":"system","parameters":[{"id":"ac-24.01_odp.01","label":"access authorization information"},{"id":"ac-24.01_odp.02","label":"controls"},{"id":"ac-24.01_odp.03","label":"systems"}],"methods":[{"method":"examine","label":"AC-24(01)-Examine"},{"method":"interview","label":"AC-24(01)-Interview"},{"method":"test","label":"AC-24(01)-Test"}],"related_controls":["AU-10"],"is_enhancement":true,"parent_id":"AC-24"},{"id":"AC-24(2)","oscal_id":"ac-24.2","family":"AC","title":"No User or Process Identity","statement":"Enforce access control decisions based on <organization-defined security or privacy attributes> that do not include the identity of the user or process acting on behalf of the user.","supplemental_guidance":"In certain situations, it is important that access control decisions can be made without information regarding the identity of the users issuing the requests. These are generally instances where preserving individual privacy is of paramount importance. In other situations, user identification information is simply not needed for access control decisions, and especially in the case of distributed systems, transmitting such information with the needed degree of assurance may be very expensive or difficult to accomplish. MAC, RBAC, ABAC, and label-based control policies, for example, might not include user identity as an attribute.","implementation_level":"system","parameters":[{"id":"ac-24.2_prm_1","label":"organization-defined security or privacy attributes"},{"id":"ac-24.02_odp.01","label":"security attributes"},{"id":"ac-24.02_odp.02","label":"privacy attributes"}],"objectives":[{"id":"ac-24.2_obj-1","label":"AC-24(02)[01]","text":"access control decisions are enforced based on {{ insert: param, ac-24.02_odp.01 }} that do not include the identity of the user or process acting on behalf of the user (if selected);"},{"id":"ac-24.2_obj-2","label":"AC-24(02)[02]","text":"access control decisions are enforced based on {{ insert: param, ac-24.02_odp.02 }} that do not include the identity of the user or process acting on behalf of the user (if selected)."}],"methods":[{"method":"examine","label":"AC-24(02)-Examine"},{"method":"interview","label":"AC-24(02)-Interview"},{"method":"test","label":"AC-24(02)-Test"}],"is_enhancement":true,"parent_id":"AC-24"}]},{"id":"AC-25","oscal_id":"ac-25","family":"AC","title":"Reference Monitor","statement":"Implement a reference monitor for <access control policies> that is tamperproof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.","supplemental_guidance":"A reference monitor is a set of design requirements on a reference validation mechanism that, as a key component of an operating system, enforces an access control policy over all subjects and objects. A reference validation mechanism is always invoked, tamper-proof, and small enough to be subject to analysis and tests, the completeness of which can be assured (i.e., verifiable). Information is represented internally within systems using abstractions known as data structures. Internal data structures can represent different types of entities, both active and passive. Active entities, also known as subjects, are associated with individuals, devices, or processes acting on behalf of individuals. Passive entities, also known as objects, are associated with data structures, such as records, buffers, communications ports, tables, files, and inter-process pipes. Reference monitors enforce access control policies that restrict access to objects based on the identity of subjects or groups to which the subjects belong. The system enforces the access control policy based on the rule set established by the policy. The tamper-proof property of the reference monitor prevents determined adversaries from compromising the functioning of the reference validation mechanism. The always invoked property prevents adversaries from bypassing the mechanism and violating the security policy. The smallness property helps to ensure completeness in the analysis and testing of the mechanism to detect any weaknesses or deficiencies (i.e., latent flaws) that would prevent the enforcement of the security policy.","implementation_level":"system","parameters":[{"id":"ac-25_odp","label":"access control policies"}],"methods":[{"method":"examine","label":"AC-25-Examine"},{"method":"interview","label":"AC-25-Interview"},{"method":"test","label":"AC-25-Test"}],"related_controls":["AC-3","AC-16","SA-8","SA-17","SC-3","SC-11","SC-39","SI-13"]}]};
